{"command": "cat <<'EOF' > /tmp/pty.py
import os, pty, sys, time, select, fcntl, termios, struct
def run(cmd, cols, rows, keys, outfile, settle=1.5):
    pid, fd = pty.fork()
    if pid == 0:
        os.environ['TERM']='xterm-256color'
        os.environ['COLUMNS']=str(cols); os.environ['LINES']=str(rows)
        os.execvp(cmd[0], cmd)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out = bytearray()
    def drain(t=0.4):
        end = time.time()+t
        while time.time() < end:
            r,_,_ = select.select([fd], [], [], 0.1)
            if r:
                try:
                    d = os.read(fd, 65536)
                except OSError:
                    return False
                if not d: return False
                out.extend(d)
                end = time.time()+t
        return True
    drain(settle)
    for k in keys:
        out.extend(('<<KEY:%s>>'%k).encode())
        if isinstance(k,str):
            os.write(fd, k.encode())
        else:
            os.write(fd, k)
        if not drain(1.0): break
    os.write(fd, b'q'); drain(0.5)
    try: os.close(fd)
    except OSError: pass
    try: os.waitpid(pid, os.WNOHANG)
    except ChildProcessError: pass
    open(outfile,'wb').write(bytes(out))
    return bytes(out)
if __name__ == '__main__':
    import json
    cfg = json.loads(sys.argv[1])
    out = run(cfg['cmd'], cfg.get('cols',100), cfg.get('rows',30), cfg.get('keys',[]), cfg['out'])
    print(len(out))
EOF
