import unicodedata
def wcwidth(ch):
    if unicodedata.combining(ch): return 0
    if unicodedata.east_asian_width(ch) in ('W','F'): return 2
    return 1
class Style:
    __slots__=('bold','italic','underline','reverse','dim','hidden','fg','bg')
    def __init__(self):
        self.bold=False; self.italic=False; self.underline=False; self.reverse=False
        self.dim=False; self.hidden=False; self.fg=None; self.bg=None
    def copy(self):
        s=Style(); s.bold=self.bold; s.italic=self.italic; s.underline=self.underline
        s.reverse=self.reverse; s.dim=self.dim; s.hidden=self.hidden
        s.fg=self.fg; s.bg=self.bg; return s
    def key(self):
        return (self.bold,self.italic,self.underline,self.reverse,self.dim,self.hidden,self.fg,self.bg)
    def __repr__(self):
        parts=[]
        if self.bold: parts.append('b')
        if self.italic: parts.append('i')
        if self.underline: parts.append('u')
        if self.reverse: parts.append('r')
        if self.dim: parts.append('d')
        if self.hidden: parts.append('h')
        parts.append('fg=%s'%self.fg)
        parts.append('bg=%s'%self.bg)
        return '<%s>'%','.join(parts)
def apply(style, seq):
    toks = seq.split(';') if seq else ['0']
    i=0; n=len(toks)
    while i<n:
        t=toks[i]; v=int(t) if t.isdigit() else 0
        if v==0: st=Style.__new__(Style); st.__init__()
        elif v==1: style.bold=True
        elif v==2: style.dim=True
        elif v==3: style.italic=True
        elif v==4: style.underline=True
        elif v==5: style.dim=True  # blink treated as dim-ish; keep separate flag
        elif v==6: style.hidden=False
        elif v==7: style.reverse=True
        elif v==8: style.hidden=True
        elif v==9: pass
        elif v==21: style.underline=True
        elif v==22: style.bold=False; style.dim=False
        elif v==23: style.italic=False
        elif v==24: style.underline=False
        elif v==25: style.dim=False
        elif v==27: style.reverse=False
        elif v==28: style.hidden=False
        elif v==29: pass
        elif 30<=v<=37: style.fg=v-30
        elif v==39: style.fg=None
        elif 40<=v<=47: style.bg=v-40
        elif v==49: style.bg=None
        elif 90<=v<=97: style.fg=8+(v-90)
        elif 100<=v<=107: style.bg=8+(v-100)
        elif v==38 or v==48:
