EOF
mkdir -p src; cat > src/fmt.rs <<'EOF'
//! Byte-count formatting helpers, matching the original tool's output layout.

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Format {
    Metric,
    Binary,
    Bytes,
    Gb,
    Gib,
    Mb,
    Mib,
}

impl Format {
    pub fn from_str(s: &str) -> Option<Format> {
        Some(match s {
            "metric" => Format::Metric,
            "binary" => Format::Binary,
            "bytes" => Format::Bytes,
            "gb" => Format::Gb,
            "gib" => Format::Gib,
            "mb" => Format::Mb,
            "mib" => Format::Mib,
            _ => return None,
        })
    }

    /// Format `bytes` into a fixed-width column string.
    pub fn format(&self, bytes: u64) -> String {
        match self {
            Format::Binary => {
                const K: f64 = 1024.0;
                if bytes > 1_099_511_627_776 {
                    format!("{:7.2} TiB", bytes as f64 / (K * K * K * K))
                } else if bytes > 1_073_741_824 {
                    format!("{:7.2} GiB", bytes as f64 / (K * K * K))
                } else if bytes > 1_048_576 {
                    format!("{:7.2} MiB", bytes as f64 / (K * K))
                } else if bytes > 1024 {
                    format!("{:7.2} KiB", bytes as f64 / K)
                } else {
                    format!("{:7}   B", bytes)
                }
            }
            Format::Metric => {
                if bytes > 1_000_000_000_000 {
                    format!("{:7.2} TB", bytes as f64 / 1e12)
                } else if bytes > 1_000_000_000 {
                    format!("{:7.2} GB", bytes as f64 / 1e9)
                } else if bytes > 1_000_000 {
                    format!("{:7.2} MB", bytes as f64 / 1e6)
                } else if bytes > 1000 {
                    format!("{:7.2} KB", bytes as f64 / 1000.0)
                } else {
                    format!("{:7}  B", bytes)
                }
            }
            Format::Bytes => format!("{:10} b", bytes),
            Format::Gb => format!("{:7.2} GB", bytes as f64 / 1e9),
            Format::Gib => format!("{:6.2} GiB", bytes as f64 / (1024.0 * 1024.0 * 1024.0)),
            Format::Mb => format!("{:9.2} MB", bytes as f64 / 1e6),
            Format::Mib => format!("{:8.2} MiB", bytes as f64 / (1024.0 * 1024.0)),
        }
    }
}
EOF
echo done"}

