{"command": "cd /workspace && cat > src/cli.rs <<'RSEOF'
//! Hand written argument parser that mimics the layout/behaviour of the
//! original `clap` based command line interface.

use std::io::{IsTerminal, Write};

pub const VERSION: &str = "2.32.2";
pub const APP_NAME: &str = "dua";

/// Styles used when the target stream is a terminal.
pub struct Sty {
    pub on: bool,
}

impl Sty {
    pub fn bold(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[1m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    pub fn header(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[1m\x1b[4m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    pub fn red_bold(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[1m\x1b[31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    pub fn yellow(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    pub fn green(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

/// The sub-commands understood by the CLI.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Sub {
    Interactive,
    Aggregate,
    Completions,
    None,
}

