  -h, --help            Print help
";

const COMPLETIONS_HELP: &str = "Generate shell completions

Usage: $BIN$ completions <SHELL>

Arguments:
  <SHELL>  The shell to generate a completions-script for [possible values: bash, elvish, fish, powershell, zsh]

Options:
  -h, --help  Print help
";

const HELP_HELP: &str = "Print this message or the help of the given subcommand(s)

Usage: $BIN$ help [COMMAND]...

Arguments:
  [COMMAND]...  Print help for the subcommand(s)
";

fn subst(s: &str, bin: &str) -> String {
    s.replace("$BIN$", bin)
}

/// Render the root long help with terminal styling applied to the usual spots.
fn colorize_long(s: &str, sty: &Sty) -> String {
    // Headers
    for h in [
        "Usage: dua [FLAGS] [OPTIONS] [SUBCOMMAND] [INPUT]...",
        "Commands:",
        "Arguments:",
        "Options:",
    ] {
        let head = h.split(' ').next().unwrap_or(h).to_string();
        s = s.replace(&format!("\n{}", h), &format!("\n{}{}", sty.header(&head), &h[head.len()..]));
    }
    s = s.replace(
        &format!("{} dua [FLAGS]", sty.header("Usage:")),
        &format!("{} dua [FLAGS]", sty.header("Usage:")),
    );
    for cmd in ["interactive", "aggregate", "completions", "help"] {
        s = s.replace(&format!("  {}\n", cmd), &format!("  {}\n", sty.bold(cmd)));
    }
    for (short, long) in [
        ("-t", "--threads"),
        ("-f", "--format"),
        ("-A", "--apparent-size"),
        ("-l", "--count-hard-links"),
        ("-x", "--stay-on-filesystem"),
        ("-i", "--ignore-dirs"),
        ("", "--log-file"),
        ("-h", "--help"),
        ("-V", "--version"),
    ] {
        if short.is_empty() {
            s = s.replace(&format!("      {}\n", long), &format!("      {}\n", sty.bold(long)));
        } else {
            s = s.replace(&format!("  {}, {}\n", short, long), &format!("  {}, {}\n", sty.bold(short), sty.bold(long)));
        }
    }
    s.replace("$BLANK$", "          ")
}

/// Compact (short) help rendering.
fn colorize_short(s: &str, sty: &Sty) -> String {
    for h in ["Usage: dua [FLAGS]", "Commands:", "Arguments:", "Options:"] {
        let head = h.split(' ').next().unwrap_or(h).to_string();
        s = s.replace(&format!("\n{}", h), &format!("\n{}{}", sty.header(&head), &h[head.len()..]));
    }
    for cmd in ["interactive", "aggregate", "completions", "help"] {
        s = s.replace(&format!("  {} ", cmd), &format!("  {} ", sty.bold(cmd)));
    }
    for (short, long) in [
        ("-t", "--threads"),
        ("-f", "--format"),
        ("-A", "--apparent-size"),
        ("-l", "--count-hard-links"),
        ("-x", "--stay-on-filesystem"),
        ("-i", "--ignore-dirs"),
        ("", "--log-file"),
        ("-h", "--help"),
        ("-V", "--version"),
    ] {
        if short.is_empty() {
            s = s.replace(&format!("      {} ", long), &format!("      {} ", sty.bold(long)));
        } else {
            s = s.replace(&format!("  {}, {} ", short, long), &format!("  {}, {} ", sty.bold(short), sty.bold(long)));
        }
    }
    s
}

fn colorize_sub(s: &str, bin: &str, sub: &str, sty: &Sty, header: &str) -> String {
    let path = format!("{} {}", bin, sub);
    let bold_path = sty.bold(&path);
    s = s.replace(&header, &sty.header(&header));
    s = s.replace(&format!("Usage: {}", path), &format!("Usage: {}", bold_path));
    // bold the flags
    let mut out = String::new();
    for line in s.split('\n') {
        if line.starts_with("      --") || line.starts_with("  -") {
            let mut l = String::new();
            let mut rest = line;
            let indent_len = line.len() - line.trim_start_matches(' ').len();
            l.push_str(&line[..indent_len]);
            rest = &line[indent_len..];
            // split at the end of the flag part: the flags are up to the first space after them
            let flags_end = rest.find("  ").unwrap_or(rest.len());
            let flags = &rest[..flags_end];
            let desc = &rest[flags_end..];
            let mut first = true;
            for tok in flags.split(' ') {
                if tok.is_empty() {
                    continue;
                }
                if !first {
                    l.push(' ');
                }
                if tok == "," {
                    l.push_str(", ");
                    first = true;
                    continue;
                }
                l.push_str(&sty.bold(tok));
                first = false;
            }
            l.push_str(desc);
            out.push_str(&l);
            out.push('\n');
        } else if line.starts_with("  [") || line.starts_with("  <") {
            out.push_str(line);
            out.push('\n');
        } else {
            out.push_str(line);
            out.push('\n');
        }
    }
    // drop the trailing newline duplication handled by caller
    out
}

pub struct Cli {
    pub bin: String,
}

pub enum Action {
    PrintRootLong,
    PrintRootShort,
    PrintSub(&'static str), // which sub help
    Version,
    Completions(String),
    Run(Parsed),
    Error(String),
}

impl Cli {
    pub fn new(argv0: &str) -> Cli {
        let bin = std::path::Path::new(argv0)
            .file_name()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| argv0.to_string());
        Cli { bin }
    }

    fn err(&self, msg: String) -> Action {
        let sty = Sty { on: std::io::stderr().is_terminal() };
        let out = format!(
            "{}error:{} {}{}\n\n{}Usage:{} {}\n\nFor more information, try '{}--help{}'.\n",
            if sty.on { "\x1b[1m\x1b[31m" } else { "" },
            if sty.on { "\x1b[0m" } else { "" },
            msg,
            "",
            if sty.on { "\x1b[1m\x1b[4m" } else { "" },
            if sty.on { "\x1b[0m" } else { "" },
            "",
            if sty.on { "\x1b[1m" } else { "" },
            if sty.on { "\x1b[0m" } else { "" },
        );
        Action::Error(out)
    }
}
RSEOF
echo written"}

