fn render_sub(s: &str, bin: &str, color: bool) -> String {
    let out = s.replace("$BIN$", bin);
    render(&out, color)
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Sub {
    Interactive,
    Aggregate,
    Completions,
    None,
}

#[derive(Default)]
pub struct Parsed {
    pub threads: u32,
    pub format: crate::fmt::Format,
    pub apparent_size: bool,
    pub count_hard_links: bool,
    pub stay_on_fs: bool,
    pub ignore_dirs: Vec<String>,
    pub log_file: Option<String>,
    pub inputs: Vec<String>,
    pub sub: Sub,
    pub aggregate: Option<(bool, bool, bool)>,
    pub interactive: Option<bool>,
    pub completions: Option<String>,
}

pub enum Action {
    Help(String),
    Version,
    Completions(String),
    Run(Parsed),
    Error(String),
}

pub struct Cli {
    pub bin: String,
    stdout_color: bool,
    stderr_color: bool,
}

impl Cli {
    pub fn new(argv0: &str) -> Cli {
        let bin = std::path::Path::new(argv0)
            .file_name()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| argv0.to_string());
        Cli {
            bin,
            stdout_color: std::io::stdout().is_terminal(),
            stderr_color: std::io::stderr().is_terminal(),
        }
    }

    pub fn root_long(&self) -> String {
        render(ROOT_LONG, self.stdout_color)
    }
    pub fn root_short(&self) -> String {
        render(ROOT_SHORT, self.stdout_color)
    }
    pub fn aggregate_help(&self) -> String {
        render_sub(AGGREGATE_HELP, &self.bin, self.stdout_color)
    }
    pub fn interactive_help(&self) -> String {
        render_sub(INTERACTIVE_HELP, &self.bin, self.stdout_color)
    }
    pub fn completions_help(&self) -> String {
        render_sub(COMPLETIONS_HELP, &self.bin, self.stdout_color)
    }
    pub fn help_help(&self) -> String {
        render_sub(HELP_HELP, &self.bin, self.stdout_color)
    }
    pub fn version(&self) -> String {
        format!("{} {}\n", APP_NAME, VERSION)
    }

    fn usage_for(&self, sub: Sub) -> String {
        match sub {
            Sub::None => {
                let u = format!("{{U}}Usage:{{/}} {}", ROOT_USAGE);
                render(&u, self.stderr_color)
            }
            _ => {
                let name = match sub {
                    Sub::Aggregate => "aggregate",
                    Sub::Interactive => "interactive",
                    Sub::Completions => "completions",
                    Sub::None => "",
                };
                render(
                    &format!("{{U}}Usage:{{/}} {{B}}{} {}{{/}}", self.bin, name),
                    self.stderr_color,
                )
            }
        }
    }

    pub fn error(&self, msg: &str, sub: Sub, usage: bool) -> Action {
        let tail = if usage {
            format!("\n{}\n", self.usage_for(sub))
        } else {
            String::new()
        };
        Action::Error(format!(
            "{}error{{/}} {}\n{}For more information, try '{}--help{{/}}'.\n",
            render(&format!("{{R}}", ), self.stderr_color),
            msg,
            tail,
            render(&format!("{{B}}"), self.stderr_color),
        ))
    }

    fn err_fmt(&self, msg: &str, sub: Sub, with_usage: bool) -> Action {
        let c = self.stderr_color;
        let head = if c {
            "\x1b[1m\x1b[31merror:\x1b[0m"
        } else {
            "error:"
        };
        let usage = if with_usage {
            format!("\n{}\n", self.usage_for(sub))
        } else {
            String::new()
        };
        Action::Error(format!(
            "{} {}\n{}\nFor more information, try '{}--help{}'..\n",
            head,
            msg,
            usage,
            if c { "\x1b[1m" } else { "" },
            if c { "\x1b[0m" } else { "" }
        ))
    }

    fn unexpected(&self, arg: &str, sub: Sub) -> Action {
        let c = self.stderr_color;
        let msg = format!(
            "unexpected argument '{}' found",
            if c {
                format!("\x1b[33m{}\x1b[0m", arg)
            } else {
                arg.to_string()
            }
        );
        let tip = format!(
            "\n  {} to pass '{}' as a value, use '{}'\n",
            if c { "\x1b[32mtip:\x1b[0m" } else { "tip:" },
            if c {
                format!("\x1b[33m{}\x1b[0m", arg)
            } else {
                arg.to_string()
            },
            if c {
                format!("\x1b[32m-- {}\x1b[0m", arg)
            } else {
                format!("-- {}", arg)
            }
        );
        Action::Error(format!(
            "{} {}\n{}{}\nFor more information, try '{}--help{}'..\n",
            if c { "\x1b[1m\x1b[31merror:\x1b[0m" } else { "error:" },
            msg,
            tip,
            self.usage_for(sub),
            if c { "\x1b[1m" } else { "" },
            if c { "\x1b[0m" } else { "" }
        ))
    }

    fn invalid_value(&self, val: &str, arg: &str, possible: Option<&[&str]>, extra: Option<&str>) -> Action {
        let c = self.stderr_color;
        let mut msg = format!(
            "invalid value '{}' for '{}'",
            if c { format!("\x1b[33m{}\x1b[0m", val) } else { val.to_string() },
            if c {
                format!("\x1b[1m{}\x1b[0m", arg)
            } else {
                arg.to_string()
            }
        );
        if let Some(e) = extra {
            msg.push_str(&format!(": {}", e));
        }
        msg.push('\n');
        if let Some(p) = possible {
            let vals: Vec<String> = p
                .iter()
                .map(|v| {
                    if c {
                        format!("\x1b[32m{}\x1b[0m", v)
                    } else {
                        v.to_string()
                    }
                })
                .collect();
            msg.push_str(&format!("  [possible values: {}]\n", vals.join(", ")));
        }
        Action::Error(format!(
            "{} {}\n\nFor more information, try '{}--help{}'..\n",
            if c { "\x1b[1m\x1b[31merror:\x1b[0m" } else { "error:" },
            msg.trim_end_matches('\n'),
            if c { "\x1b[1m" } else { "" },
            if c { "\x1b[0m" } else { "" }
        ))
    }
}
RSEOF
echo ok"}

