{"command": "cd /workspace && cat >> src/cli.rs <<'RSEOF'

const FORMATS: [&str; 7] = ["metric", "binary", "bytes", "gb", "gib", "mb", "mib"];
const SHELLS: [&str; 5] = ["bash", "elvish", "fish", "powershell", "zsh"];

struct Ctx {
    p: Parsed,
    /// Number of positional arguments consumed so far (sub-command detection
    /// only happens for the very first one).
    positionals: usize,
    end_of_opts: bool,
    sub: Sub,
}

impl Ctx {
    fn new() -> Ctx {
        Ctx {
            p: Parsed {
                format: crate::fmt::Format::Binary,
                ..Default::default()
            },
            positionals: 0,
            end_of_opts: false,
            sub: Sub::None,
        }
    }
}

fn lookup_sub(s: &str) -> Option<Sub> {
    match s {
        "interactive" | "i" => Some(Sub::Interactive),
        "aggregate" | "a" => Some(Sub::Aggregate),
        "completions" => Some(Sub::Completions),
        _ => None,
    }
}

impl Cli {
    pub fn parse(&self, args: &[String]) -> Action {
        let mut ctx = Ctx::new();
        let mut i = 0usize;
        let n = args.len();
        while i < n {
            let a = args[i].clone();
            i += 1;
            if !ctx.end_of_opts && a == "--" {
                ctx.end_of_opts = true;
                continue;
            }
            if !ctx.end_of_opts && a.starts_with("--") && a.len() > 2 {
                match self.long_opt(&a, &mut ctx, args, &mut i) {
                    Some(act) => return act,
                    None => continue,
                }
            }
            if !ctx.end_of_opts && a.starts_with('-') && a.len() > 1 {
                match self.short_opt(&a, &mut ctx, args, &mut i) {
                    Some(act) => return act,
                    None => continue,
                }
            }
            // positional
            if ctx.sub == Sub::None && ctx.positionals == 0 {
                if let Some(sub) = lookup_sub(&a) {
                    ctx.sub = sub;
                    ctx.positionals += 1;
                    continue;
                }
                if a == "help" {
                    return self.handle_help(&args[i..]);
                }
            }
            ctx.positionals += 1;
            match ctx.sub {
                Sub::None => ctx.p.inputs.push(a),
                Sub::Completions => {
                    if ctx.p.completions.is_some() {
                        return self.unexpected(&a, Sub::Completions);
                    }
                    if !SHELLS.contains(&a.as_str()) {
                        return self.invalid_value(&a, "<SHELL>", Some(&SHELLS), None);
                    }
                    ctx.p.completions = Some(a);
                }
                _ => ctx.p.inputs.push(a),
            }
        }
        self.finish(ctx)
    }

    fn handle_help(&self, rest: &[String]) -> Action {
        if rest.is_empty() {
            return Action::Help(self.root_long());
        }
        let first = &rest[0];
        let sub = match lookup_sub(first) {
            Some(s) => s,
            None => {
                if first == "help" {
                    return Action::Help(self.help_help());
                }
                return self.unrecognized_sub(first, Sub::None);
            }
        };
        if rest.len() > 1 {
            return self.unrecognized_sub(&rest[1], sub);
        }
        Action::Help(match sub {
            Sub::Aggregate => self.aggregate_help(),
            Sub::Interactive => self.interactive_help(),
            Sub::Completions => self.completions_help(),
            Sub::None => self.root_long(),
        })
    }

    fn finish(&self, ctx: Ctx) -> Action {
        let sub = ctx.sub;
        match sub {
            Sub::Completions => match ctx.p.completions.clone() {
                Some(shell) => Action::Completions(shell),
                None => self.missing_required(&["<SHELL>"], Sub::Completions),
            },
            _ => Action::Run(ctx.p),
        }
    }

    /// Returns Some(action) when parsing should stop (help/version/error).
    #[allow(clippy::too_many_arguments)]
    fn long_opt(&self, arg: &str, ctx: &mut Ctx, args: &[String], i: &mut usize) -> Option<Action> {
        let body = &arg[2..];
        let (name, inline) = match body.find('=') {
            Some(pos) => (&body[..pos], Some(body[pos + 1..].to_string())),
            None => (body, None),
        };
        self.opt(name, true, inline, ctx, args, i)
    }

    fn short_opt(&self, arg: &str, ctx: &mut Ctx, args: &[String], i: &mut usize) -> Option<Action> {
        let chars: Vec<char> = arg[1..].chars().collect();
        let mut k = 0usize;
        while k < chars.len() {
            let c = chars[k];
            k += 1;
            let rest: String = chars[k..].iter().collect();
            let rest = if rest.starts_with('=') { rest[1..].to_string() } else { rest };
            let inline = if rest.is_empty() { None } else { Some(rest) };
            let name: String = match c {
                't' => "threads".to_string(),
                'f' => "format".to_string(),
                'A' => "apparent-size".to_string(),
                'l' => "count-hard-links".to_string(),
                'x' => "stay-on-filesystem".to_string(),
                'i' => "ignore-dirs".to_string(),
                'e' => "no-entry-check".to_string(),
                'h' => "help".to_string(),
                'V' => "version".to_string(),
                other => {
                    let bad = format!("-{}", other);
                    if !ctx.end_of_opts {
                        return Some(self.unexpected(&bad, ctx.sub));
                    }
                    return Some(self.unexpected(&bad, ctx.sub));
                }
            };
            match self.opt(&name, false, inline, ctx, args, i) {
                Some(act) => return Some(act),
                None => {}
            }
            if inline.is_some() {
                break;
            }
        }
        None
    }

    fn opt(
        &self,
        name: &str,
        _long: bool,
        inline: Option<String>,
        ctx: &mut Ctx,
        args: &[String],
        i: &mut usize,
    ) -> Option<Action> {
        let take_value = |inline: Option<String>, i: &mut usize| -> Option<String> {
            match inline {
                Some(v) => Some(v),
                None => {
                    if *i < args.len() {
                        let v = args[*i].clone();
                        *i += 1;
                        Some(v)
                    } else {
                        None
                    }
                }
            }
        };
        match ctx.sub {
            Sub::None => match name {
                "threads" => {
                    let v = match take_value(inline, i) {
                        Some(v) => v,
                        None => return Some(self.missing_value("--threads <THREADS>", None)),
                    };
                    match v.parse::<usize>() {
                        Ok(t) => {
                            if ctx.p.threads_seen {
                                return Some(self.dup("--threads <THREADS>", Sub::None));
                            }
                            ctx.p.threads_seen = true;
                            ctx.p.threads = t.min(1024) as u32;
                        }
                        Err(e) => {
                            return Some(self.invalid_value(&v, "--threads <THREADS>", None, Some(&e.to_string())))
                        }
                    }
                }
                "format" => {
                    let v = match take_value(inline, i) {
                        Some(v) => v,
                        None => return Some(self.missing_value("--format <FORMAT>", Some(&FORMATS))),
                    };
                    match crate::fmt::Format::from_str(&v) {
                        Some(f) => {
                            if ctx.p.format_seen {
                                return Some(self.dup("--format <FORMAT>", Sub::None));
                            }
                            ctx.p.format_seen = true;
                            ctx.p.format = f;
                        }
                        None => {
                            return Some(self.invalid_value(&v, "--format <FORMAT>", Some(&FORMATS), None))
                        }
                    }
                }
                "apparent-size" => {
                    if ctx.p.apparent_size {
                        return Some(self.dup("--apparent-size", Sub::None));
                    }
                    ctx.p.apparent_size = true;
                }
                "count-hard-links" => {
                    if ctx.p.count_hard_links {
                        return Some(self.dup("--count-hard-links", Sub::None));
                    }
                    ctx.p.count_hard_links = true;
                }
                "stay-on-filesystem" => {
                    if ctx.p.stay_on_fs {
