                    nt = true;
                    ctx.p.aggregate = Some((s, ns, nt));
                }
                "help" => return Some(Action::Help(self.aggregate_help())),
                _ => return Some(self.unexpected(&format!("--{}", name), Sub::Aggregate)),
            },
            Sub::Interactive => match name {
                "no-entry-check" => {
                    if ctx.p.interactive == Some(true) {
                        return Some(self.dup("--no-entry-check", Sub::Interactive));
                    }
                    ctx.p.interactive = Some(true);
                }
                "help" => return Some(Action::Help(self.interactive_help())),
                _ => return Some(self.unexpected(&format!("--{}", name), Sub::Interactive)),
            },
            Sub::Completions => match name {
                "help" => return Some(Action::Help(self.completions_help())),
                _ => return Some(self.unexpected(&format!("--{}", name), Sub::Completions)),
            },
        }
        None
    }

    fn dup(&self, arg: &str, sub: Sub) -> Action {
        Action::Error(self.build(
            &format!("the argument '{}' cannot be used multiple times", self.yellow(arg)),
            None,
            sub,
            true,
        ))
    }
}
