//! Parallel directory traversal and the `aggregate` output rendering.

use crate::cli::Parsed;
use crate::fmt::Format;
use std::collections::{BTreeSet, HashSet};
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Mutex};

/// One node of the collected tree.
pub struct Node {
    /// Display name (file name for traversal results, input text otherwise).
    pub name: String,
    /// Size of the entry itself (disk usage or apparent size).
    pub size: u64,
    /// Total size of the entry and all its children.
    pub total: u64,
    /// Number of entries in the subtree, including this one.
    pub count: u64,
    pub is_dir: bool,
    pub children: Vec<usize>,
}

pub struct Graph {
    pub nodes: Vec<Node>,
    pub io_errors: u64,
    pub entries_traversed: u64,
    pub smallest: u64,
    pub largest: u64,
}

struct Shared {
    nodes: Vec<Node>,
    queue: Vec<(usize, PathBuf, bool, Option<u64>)>,
    inodes: HashSet<(u64, u64)>,
    count: u64,
    traversed: u64,
    smallest: u64,
    largest: u64,
}

fn own_size(md: &fs::Metadata, apparent: bool) -> u64 {
    if apparent {
        md.len()
    } else {
        md.blocks() * 512
    }
}

fn build(
    inputs: &[String],
    apparent: bool,
    hard_links: bool,
    stay_on_fs: bool,
    ignore: &BTreeSet<String>,
    threads: usize,
) -> Graph {
    let mut nodes: Vec<Node> = Vec::new();
    let mut io_errors: u64 = 0;
    let mut roots: Vec<usize> = Vec::new();
    let mut shared = Shared {
        nodes: Vec::new(),
        queue: Vec::new(),
        inodes: HashSet::new(),
        count: 0,
        traversed: 0,
        smallest: 0,
        largest: 0,
    };

    for input in inputs {
        let path = PathBuf::from(input);
        match fs::metadata(&path) {
            Ok(md) => {
                let size = own_size(&md, apparent);
                let id = nodes.len();
                nodes.push(Node {
                    name: input.clone(),
                    size: 0,
                    total: size,
                    count: 1,
                    is_dir: md.is_dir(),
                    children: Vec::new(),
                });
                if md.is_dir() {
                    shared.queue.push((id, path, true, md.dev().ok()));
                } else if !md.is_dir() {
                    // file or special entry
                    let sz = if md.file_type().is_symlink() { 0 } else { size };
                    nodes[id].size = sz;
                    nodes[id].total = sz;
                    track(&mut shared, sz);
                }
                roots.push(id);
            }
            Err(_) => {
                io_errors += 1;
                let id = nodes.len();
                nodes.push(Node {
                    name: input.clone(),
                    size: 0,
                    total: 0,
                    count: 1,
                    is_dir: true,
                    children: Vec::new(),
                });
                roots.push(id);
            }
        }
    }

    // Move the remaining work into the shared state and process it.
    shared.nodes = nodes;
    let shared = Arc::new(Mutex::new(shared));
    let stop = Arc::new(AtomicBool::new(false));
    let _ = &stop;
    let nthreads = if threads == 0 {
        std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
    } else {
        threads
    };
    let cfg = Cfg {
        apparent,
        hard_links,
        stay_on_fs,
        ignore: ignore.clone(),
    };

    if nthreads <= 1 {
        let mut guard = shared.lock().unwrap();
        while let Some(task) = guard.queue.pop() {
            drop(guard);
            process_task(&shared, task, &cfg);
            guard = shared.lock().unwrap();
        }
    } else {
        let mut handles = Vec::new();
        for _ in 0..nthreads {
            let sh = shared.clone();
            let cfg = cfg.clone();
            handles.push(std::thread::spawn(move || {
                loop {
                    let task = {
                        let mut g = sh.lock().unwrap();
                        g.queue.pop()
                    };
                    match task {
                        Some(t) => process_task(&sh, t, &cfg),
                        None => break,
                    }
                }
            }));
        }
        for h in handles {
            let _ = h.join();
        }
    }

    let mut shared = Arc::try_unwrap(shared).ok();
    let shared = match shared.as_mut() {
        Some(s) => s,
        None => {
            let mut nodes = Vec::new();
            if let Ok(g) = Arc::try_unwrap(shared) {
                nodes = g.nodes;
            }
            let _ = nodes;
            unreachable!()
        }
    };
