    // Finalise the totals bottom-up (children first).
    compute_totals(&mut nodes, &roots[..]);
    Graph {
        nodes,
        io_errors,
        entries_traversed: shared.traversed,
        smallest: shared.smallest,
        largest: shared.largest,
    }
}

fn track(shared: &mut Shared, size: u64) {
    if shared.count == 0 {
        shared.smallest = size;
        shared.largest = size;
    } else {
        if size < shared.smallest {
            shared.smallest = size;
        }
        if size > shared.largest {
            shared.largest = size;
        }
    }
    shared.count += 1;
}

fn compute_totals(nodes: &mut [Node], _roots: &[usize]) {
    for i in (0..nodes.len()).rev() {
        let mut total = nodes[i].size;
        let mut count = 1u64;
        let children = nodes[i].children.clone();
        for c in children {
            total += nodes[c].total;
            count += nodes[c].count;
        }
        nodes[i].total = total;
        nodes[i].count = count;
    }
}

#[derive(Clone)]
struct Cfg {
    apparent: bool,
    hard_links: bool,
    stay_on_fs: bool,
    ignore: BTreeSet<String>,
}

fn process_task(sh: &Arc<Mutex<Shared>>, task: (usize, PathBuf, bool, Option<u64>), cfg: &Cfg) {
    let (id, path, is_root, dev) = task;
    let entries = match fs::read_dir(&path) {
        Ok(e) => e,
        Err(_) => return,
    };
    let mut children: Vec<(String, Node, Option<PathBuf>, Option<u64>)> = Vec::new();
    let mut found: Vec<String> = Vec::new();
    for ent in entries.flatten() {
        let name = ent.file_name().to_string_lossy().to_string();
        let child_path = ent.path();
        let md = match fs::symlink_metadata(&child_path) {
            Ok(m) => m,
            Err(_) => continue,
        };
        let ft = md.file_type();
        if ft.is_symlink() {
            if is_root {
                continue;
            }
            children.push((
                name,
                Node {
                    name: name.clone(),
                    size: 0,
                    total: 0,
                    count: 1,
                    is_dir: false,
                    children: Vec::new(),
                },
                None,
                None,
            ));
            continue;
        }
        if ft.is_dir() {
            let abs = abs_path(&child_path);
            let ignored = cfg.ignore.contains(&abs);
            let sz = own_size(&md, cfg.apparent);
            let nd = Node {
                name: name.clone(),
                size: sz,
                total: sz,
                count: 1,
                is_dir: true,
                children: Vec::new(),
            };
            if ignored {
                children.push((name, nd, None, None));
            } else {
                let fsdev = if cfg.stay_on_fs { md.dev().ok() } else { None };
                children.push((name, nd, Some(child_path), fsdev));
            }
            continue;
        }
        let sz = own_size(&md, cfg.apparent);
        let sz = if cfg.hard_links {
            sz
        } else {
            let key = (md.dev().unwrap_or(0), md.ino().unwrap_or(0));
            let mut g = sh.lock().unwrap();
            if g.inodes.contains(&key) {
                0
            } else {
                g.inodes.insert(key);
                sz
            }
        };
        children.push((
            name,
            Node {
                name: name.clone(),
                size: sz,
                total: sz,
                count: 1,
                is_dir: false,
                children: Vec::new(),
            },
            None,
            None,
        ));
    }
    // sort children by name (byte order) for deterministic display
    children.sort_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));
    let mut g = sh.lock().unwrap();
    let mut ids = Vec::new();
    for (name, node, subdir, _dev) in children {
        let cid = g.nodes.len();
        g.nodes.push(node);
        ids.push(cid);
        if let Some(p) = subdir {
            g.queue.push((cid, p, false, None));
        }
        let _ = name;
    }
    g.nodes[id].children = ids;
    g.traversed += 1;
}

fn abs_path(p: &Path) -> String {
    match fs::canonicalize(p) {
        Ok(c) => c.to_string_lossy().to_string(),
        Err(_) => {
            if p.is_absolute() {
                p.to_string_lossy().to_string()
            } else {
                let mut s = std::env::current_dir()
                    .map(|c| c.to_string_lossy().to_string())
                    .unwrap_or_default();
                s.push('/');
                s.push_str(&p.to_string_lossy());
                s
            }
        }
    }
}

pub fn collect_ignores(ignore_dirs: &[String]) -> BTreeSet<String> {
    let mut set = BTreeSet::new();
    for d in ignore_dirs {
        if let Ok(c) = fs::canonicalize(d) {
            set.insert(c.to_string_lossy().to_string());
        }
    }
    set
}

pub struct Row {
    pub name: String,
    pub size: u64,
    pub is_dir: bool,
    pub errors: u64,
}

pub fn run(p: &Parsed) -> i32 {
    let inputs: Vec<String> = if p.inputs.is_empty() {
        let mut v = Vec::new();
        if let Ok(rd) = fs::read_dir(".") {
            for e in rd.flatten() {
                v.push(e.file_name().to_string_lossy().to_string());
            }
        }
        v
    } else {
        p.inputs.clone()
    };
    let ignore = collect_ignores(&p.ignore_dirs);
    let graph = build(
        &inputs,
        p.apparent_size,
        p.count_hard_links,
        p.stay_on_fs,
        &ignore,
        p.threads as usize,
    );
    print_graph(p, &graph, &inputs)
}

pub fn print_graph(p: &Parsed, graph: &Graph, inputs: &[String]) -> i32 {
    let mut rows: Vec<Row> = Vec::new();
    let single_dir = inputs.len() == 1 && graph.nodes.get(0).map(|n| n.is_dir).unwrap_or(false);
    if single_dir {
        let root = 0usize;
        for &c in &graph.nodes[root].children {
            let n = &graph.nodes[c];
            rows.push(Row {
                name: n.name.clone(),
                size: n.total,
                is_dir: n.is_dir,
                errors: 0,
            });
        }
    } else {
        for i in 0..graph.nodes.len().min(inputs.len()) {
            let n = &graph.nodes[i];
            rows.push(Row {
                name: n.name.clone(),
                size: n.total,
                is_dir: n.is_dir,
                errors: 0,
            });
        }
    }
    let _ = inputs;
    if !p.no_sort.unwrap_or(false) {
        // stable sort ascending by size
        let mut idx: Vec<usize> = (0..rows.len()).collect();
        idx.sort_by(|a, b| rows[*a].size.cmp(&rows[*b].size));
        let sorted: Vec<Row> = idx.into_iter().map(|i| rows.swap_remove(i)).collect();
        rows = sorted;
    }
    let total: u64 = rows.iter().map(|r| r.size).sum();
    let mut out: Vec<String> = Vec::new();
    for r in &rows {
        out.push(render_row(p.format, r, None));
    }
    if rows.len() > 1 && !p.no_total.unwrap_or(false) {
        out.push(render_row(
            p.format,
            &Row {
                name: "total".to_string(),
                size: total,
                is_dir: false,
                errors: 0,
            },
            Some(graph.io_errors),
        ));
    }
    let mut rc = 0;
    let mut reported = false;
    for line in &out {
        match writeln!(std::io::stdout(), "{}", line) {
            Ok(_) => {}
            Err(e) => {
                if !reported {
                    reported = true;
                    let _ = writeln!(std::io::stderr(), "Error: {}", e);
                }
                rc = 1;
            }
        }
    }
    let _ = std::io::stdout().flush();
    if graph.io_errors > 0 {
        rc = 1;
    }
    rc
}

pub fn render_row(f: Format, r: &Row, total_errors: Option<u64>) -> String {
    let size = f.format(r.size);
    let mut s = String::new();
    s.push_str("\x1b[32m");
    s.push_str(&size);
    s.push_str("\x1b[39m ");
    if r.is_dir {
        s.push_str("\x1b[36m");
        s.push_str(&r.name);
        s.push_str("\x1b[39m");
    } else {
        s.push_str(&r.name);
    }
    if let Some(errs) = total_errors {
        if errs > 0 {
            s.push_str(&format!("  <{} IO Error{}>", errs, if errs == 1 { "" } else { "s" }));
        }
    }
    s
}

pub fn stats_line(g: &Graph) -> String {
    format!(
        "Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}",
        g.entries_traversed, g.smallest, g.largest
    )
}
