pub struct Graph {
    pub nodes: Vec<Node>,
    pub io_errors: u64,
    pub entries_traversed: u64,
    pub smallest: u64,
    pub largest: u64,
}

struct Shared {
    nodes: Vec<Node>,
    queue: Vec<(usize, PathBuf, bool, Option<u64>)>,
    inodes: HashSet<(u64, u64)>,
    count: u64,
    traversed: u64,
    smallest: u64,
    largest: u64,
}

fn own_size(md: &fs::Metadata, apparent: bool) -> u64 {
    if apparent {
        md.len()
    } else {
        md.blocks() * 512
    }
}

