            handles.push(std::thread::spawn(move || {
                loop {
                    let task = {
                        let mut g = sh.lock().unwrap();
                        g.queue.pop()
                    };
                    match task {
                        Some(t) => process_task(&sh, t, &cfg),
                        None => break,
                    }
                }
            }));
        }
        for h in handles {
            let _ = h.join();
        }
    }

    let mut shared = Arc::try_unwrap(shared).ok();
    let shared = match shared.as_mut() {
        Some(s) => s,
        None => {
            let mut nodes = Vec::new();
            if let Ok(g) = Arc::try_unwrap(shared) {
                nodes = g.nodes;
            }
            let _ = nodes;
            unreachable!()
        }
    };
