//! Shared tree/graph construction used by both aggregate and interactive mode.

use crate::fmt::Format;
use std::collections::{BTreeSet, HashSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

#[derive(Clone)]
pub struct Options {
    pub apparent_size: bool,
    pub count_hard_links: bool,
    pub stay_on_fs: bool,
    pub ignore_dirs: BTreeSet<String>,
    pub threads: usize,
    /// Symbolic links that are direct children of a traversal root are pruned.
    pub prune_root_symlinks: bool,
}

pub struct Node {
    /// Name as shown in listings.
    pub name: String,
    /// Size of the entry itself.
    pub size: u64,
    /// Own size plus all children.
    pub total: u64,
    /// Entries in the subtree, including this node.
    pub count: u64,
    pub is_dir: bool,
    pub children: Vec<usize>,
    pub io_errors: u64,
}

pub struct Graph {
    pub nodes: Vec<Node>,
    pub root: usize,
    pub entries_traversed: u64,
    pub smallest: u64,
    pub largest: u64,
}

impl Graph {
    pub fn root_node(&self) -> &Node {
        &self.nodes[self.root]
    }
    pub fn children(&self, id: usize) -> &[usize] {
        &self.nodes[id].children
    }
    pub fn node(&self, id: usize) -> &Node {
        &self.nodes[id]
    }
    pub fn total_visible(&self) -> u64 {
        let mut t = 0u64;
        for &c in &self.nodes[self.root].children {
            t += self.nodes[c].total;
        }
        t
    }
    pub fn visible_count(&self) -> u64 {
        self.nodes[self.root].children.len() as u64
    }
    pub fn descendant_count(&self) -> u64 {
        let mut t = 0u64;
        for &c in &self.nodes[self.root].children {
            t += self.nodes[c].count;
        }
        t
    }
    pub fn io_errors(&self) -> u64 {
        self.nodes[self.root].io_errors
    }
}

struct Shared {
    nodes: Vec<Node>,
    queue: Vec<(usize, PathBuf)>,
    inodes: HashSet<(u64, u64)>,
    smallest: Option<u64>,
    largest: u64,
}

pub fn collect_ignores(ignore_dirs: &[String]) -> BTreeSet<String> {
    let mut set = BTreeSet::new();
    for d in ignore_dirs {
        if let Ok(c) = fs::canonicalize(d) {
            set.insert(c.to_string_lossy().to_string());
        }
    }
    set
}

fn own_size(md: &fs::Metadata, apparent: bool) -> u64 {
    if apparent {
        md.len()
    } else {
        md.blocks() * 512
    }
}

fn track(sh: &mut Shared, size: u64) {
    match sh.smallest {
        None => {
            sh.smallest = Some(size);
            sh.largest = size;
        }
        Some(m) => {
            if size < m {
                sh.smallest = Some(size);
            }
            if size > sh.largest {
                sh.largest = size;
            }
        }
    }
}

fn push_node(sh: &mut Shared, n: Node) -> usize {
    let id = sh.nodes.len();
    sh.nodes.push(n);
    id
}

pub fn build(inputs: &[String], opts: &Options) -> Graph {
    let mut sh = Shared {
        nodes: Vec::new(),
        queue: Vec::new(),
        inodes: HashSet::new(),
        smallest: None,
        largest: 0,
    };
    let mut roots: Vec<usize> = Vec::new();
