                let sz = own_size(&md, opts.apparent_size);
                let id = push_node(
                    &mut sh,
                    Node {
                        name: inputs[0].clone(),
                        size: sz,
                        total: sz,
                        count: 1,
                        is_dir: true,
                        children: Vec::new(),
                        io_errors: 0,
                    },
                );
                sh.queue.push((id, path.clone()));
                single_dir_root = Some((id, path));
            }
            Ok(_) => {
                need_virtual = true;
            }
            Err(_) => {
                need_virtual = true;
            }
        }
    }

    if need_virtual {
        let virtual_root = push_node(
            &mut sh,
            Node {
                name: String::new(),
                size: 0,
                total: 0,
                count: 0,
                is_dir: true,
                children: Vec::new(),
                io_errors: 0,
            },
        );
        for input in inputs {
            let path = PathBuf::from(input);
            match fs::metadata(&path) {
                Ok(md) => {
                    let size = own_size(&md, opts.apparent_size);
                    let id = push_node(
                        &mut sh,
                        Node {
                            name: input.clone(),
                            size,
                            total: size,
                            count: 1,
                            is_dir: md.is_dir(),
                            children: Vec::new(),
                            io_errors: 0,
                        },
                    );
                    track(&mut sh, size);
                    if md.is_dir() {
                        sh.queue.push((id, path));
                    }
                    sh.nodes[virtual_root].children.push(id);
                }
                Err(_) => {
                    let id = push_node(
                        &mut sh,
                        Node {
                            name: input.clone(),
                            size: 0,
                            total: 0,
                            count: 1,
                            is_dir: true,
                            children: Vec::new(),
                            io_errors: 1,
                        },
                    );
                    sh.nodes[virtual_root].children.push(id);
                    io_errors_total += 1;
                }
            }
        }
        sh.nodes[virtual_root].io_errors = io_errors_total;
    }

    let shared = Arc::new(Mutex::new(sh));
    let cfg = Arc::new(opts.clone());
    let nthreads = if opts.threads == 0 {
        std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
    } else {
        opts.threads
    };
    let nthreads = nthreads.max(1);

    if nthreads <= 1 {
        loop {
            let task = {
                let mut g = shared.lock().unwrap();
                g.queue.pop()
            };
            match task {
                Some(t) => process_task(&shared, t, &cfg),
                None => break,
            }
        }
    } else {
        let mut handles = Vec::new();
        for _ in 0..nthreads {
            let sh = shared.clone();
            let cfg = cfg.clone();
            handles.push(std::thread::spawn(move || loop {
                let task = {
                    let mut g = sh.lock().unwrap();
                    g.queue.pop()
                };
                match task {
                    Some(t) => process_task(&sh, t, &cfg),
                    None => break,
                }
            }));
        }
        for h in handles {
            let _ = h.join();
        }
    }

    let mut sh = Arc::try_unwrap(shared)
        .ok()
        .map(|m| m.into_inner().unwrap())
        .unwrap();
    let mut nodes = std::mem::take(&mut sh.nodes);
    let root = match single_dir_root {
        Some((id, _)) => id,
        None => nodes.len().saturating_sub(0),
    };
    if need_virtual {
        // virtual root was pushed first
        root = 0;
    }
    let _ = root;
    // compute totals bottom-up
    for i in (0..nodes.len()).rev() {
        let mut total = nodes[i].size;
        let mut count = 1u64;
        let children = nodes[i].children.clone();
        for c in children {
            total += nodes[c].total;
            count += nodes[c].count;
        }
        nodes[i].total = total;
        nodes[i].count = count;
    }
    let root_id = if single_dir_root.is_some() { single_dir_root.unwrap().0 } else { 0 };
    Graph {
        nodes,
        root: root_id,
        entries_traversed: 0,
        smallest: sh.smallest.unwrap_or(0),
        largest: sh.largest,
    }
}

fn abs_of(p: &Path) -> String {
    match fs::canonicalize(p) {
        Ok(c) => c.to_string_lossy().to_string(),
        Err(_) => {
            if p.is_absolute() {
                p.to_string_lossy().to_string()
            } else {
                let mut s = std::env::current_dir()
                    .map(|c| c.to_string_lossy().to_string())
                    .unwrap_or_default();
                if !s.ends_with('/') {
                    s.push('/');
                }
                s.push_str(&p.to_string_lossy());
                s
            }
        }
    }
}

fn process_task(sh: &Arc<Mutex<Shared>>, task: (usize, PathBuf), cfg: &Arc<Options>) {
    let (id, path) = task;
    let is_root = {
        let g = sh.lock().unwrap();
        // A task is a traversal root when it was queued while building the roots
        // (no parent), which we detect by checking whether the parent link exists.
        true
    };
    let _ = is_root;
    let entries = match fs::read_dir(&path) {
        Ok(e) => e,
        Err(_) => return,
    };
    let mut children: Vec<(Vec<u8>, Node, Option<PathBuf>)> = Vec::new();
    let mut n_entries = 0u64;
    for ent in entries.flatten() {
        let name_bytes = ent.file_name().as_encoded_bytes().to_vec();
        let child_path = ent.path();
        let md = match fs::symlink_metadata(&child_path) {
            Ok(m) => m,
            Err(_) => continue,
        };
        n_entries += 1;
        let ft = md.file_type();
        if ft.is_symlink() {
            if is_root {
                n_entries -= 1;
                continue;
            }
            children.push((
                name_bytes,
                Node {
                    name: String::from_utf8_lossy(&name_bytes).to_string(),
                    size: 0,
                    total: 0,
                    count: 1,
                    is_dir: false,
                    children: Vec::new(),
                    io_errors: 0,
                },
                None,
            ));
            continue;
        }
        if ft.is_dir() {
            let abs = abs_of(&child_path);
            let ignored = cfg.ignore_dirs.contains(&abs);
            let sz = own_size(&md, cfg.apparent_size);
            let nd = Node {
                name: String::from_utf8_lossy(&name_bytes).to_string(),
                size: sz,
                total: sz,
                count: 1,
                is_dir: true,
                children: Vec::new(),
                io_errors: 0,
            };
            if ignored {
                children.push((name_bytes, nd, None));
            } else {
                children.push((name_bytes, nd, Some(child_path)));
            }
            continue;
        }
        let sz = own_size(&md, cfg.apparent_size);
        let sz = if cfg.count_hard_links {
            sz
        } else {
            let key = (md.dev().unwrap_or(0), md.ino().unwrap_or(0));
            let mut g = sh.lock().unwrap();
            if g.inodes.contains(&key) {
                0
            } else {
                g.inodes.insert(key);
                sz
            }
        };
        {
            let mut g = sh.lock().unwrap();
            track(&mut g, sz);
        }
        children.push((
            name_bytes,
            Node {
                name: String::from_utf8_lossy(&name_bytes).to_string(),
                size: sz,
                total: sz,
                count: 1,
                is_dir: false,
                children: Vec::new(),
                io_errors: 0,
            },
            None,
        ));
    }
    let mut g = sh.lock().unwrap();
    let mut ids = Vec::new();
    for (_name, node, subdir) in children {
        let cid = g.nodes.len();
        g.nodes.push(node);
        ids.push(cid);
        if let Some(p) = subdir {
            g.queue.push((cid, p));
        }
    }
    ids.sort();
    g.nodes[id].children = ids;
    g.traversed += n_entries;
}
RSEOF
echo ok"}

