    }
    pub fn descendant_count(&self) -> u64 {
        self.nodes[self.root].count.saturating_sub(1)
    }
    pub fn io_errors(&self) -> u64 {
        self.nodes[self.root].io_errors
    }
    pub fn entries_traversed(&self) -> u64 {
        (self.nodes.len() as u64).saturating_sub(1)
    }
}

struct Task {
    id: usize,
    path: PathBuf,
    is_root: bool,
    dev: Option<u64>,
}

struct Shared {
    nodes: Vec<Node>,
    queue: Vec<Task>,
    inodes: HashSet<(u64, u64)>,
    smallest: Option<u64>,
    largest: u64,
}

pub fn collect_ignores(ignore_dirs: &[String]) -> BTreeSet<String> {
    let mut set = BTreeSet::new();
    for d in ignore_dirs {
        if let Ok(c) = fs::canonicalize(d) {
            set.insert(c.to_string_lossy().to_string());
        }
    }
    set
}

fn own_size(md: &fs::Metadata, apparent: bool) -> u64 {
    if apparent {
        md.len()
    } else {
        md.blocks() * 512
    }
}

fn track(sh: &mut Shared, size: u64) {
    match sh.smallest {
        None => {
            sh.smallest = Some(size);
            sh.largest = size;
        }
        Some(m) => {
            if size < m {
                sh.smallest = Some(size);
            }
            if size > sh.largest {
                sh.largest = size;
            }
        }
    }
}

fn mk_node(name: &str, size: u64, is_dir: bool, is_symlink: bool) -> Node {
    Node {
        name: name.to_string(),
        size,
        total: size,
        count: 1,
        is_dir,
        is_symlink,
        children: Vec::new(),
        io_errors: 0,
    }
}

pub fn build(inputs: &[String], opts: &Options) -> Graph {
    let mut sh = Shared {
        nodes: Vec::new(),
        queue: Vec::new(),
        inodes: HashSet::new(),
        smallest: None,
        largest: 0,
    };
    let mut single_dir_root: Option<usize> = None;

    if inputs.len() == 1 {
        let path = PathBuf::from(&inputs[0]);
        if let Ok(md) = fs::metadata(&path) {
            if md.is_dir() {
                let sz = own_size(&md, opts.apparent_size);
                let id = sh.nodes.len();
                sh.nodes.push(mk_node(&inputs[0], sz, true, false));
                sh.queue.push(Task {
                    id,
                    path,
                    is_root: true,
                    dev: md.dev().ok(),
                });
                single_dir_root = Some(id);
            }
        }
    }

