        let virtual_root = sh.nodes.len();
        sh.nodes.push(mk_node("", 0, true, false));
        let mut io_errors = 0u64;
        for input in inputs {
            let path = PathBuf::from(input);
            match fs::metadata(&path) {
                Ok(md) => {
                    let size = own_size(&md, opts.apparent_size);
                    let id = sh.nodes.len();
                    let mut n = mk_node(input, size, md.is_dir(), false);
                    n.total = size;
                    sh.nodes.push(n);
                    track(&mut sh, size);
                    if md.is_dir() {
                        sh.queue.push(Task {
                            id,
                            path,
                            is_root: true,
                            dev: md.dev().ok(),
                        });
                    }
                    sh.nodes[virtual_root].children.push(id);
                }
                Err(_) => {
                    let id = sh.nodes.len();
                    let mut n = mk_node(input, 0, true, false);
                    n.io_errors = 1;
                    sh.nodes.push(n);
                    sh.nodes[virtual_root].children.push(id);
                    io_errors += 1;
                }
            }
        }
        sh.nodes[virtual_root].io_errors = io_errors;
    }

    let shared = Arc::new(Mutex::new(sh));
    let cfg = Arc::new(opts.clone());
    let nthreads = if opts.threads == 0 {
        std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1)
    } else {
        opts.threads
    };
    let nthreads = nthreads.clamp(1, 1024);

    if nthreads <= 1 {
        loop {
            let task = {
                let mut g = shared.lock().unwrap();
                g.queue.pop()
            };
            match task {
                Some(t) => process_task(&shared, t, &cfg),
                None => break,
            }
        }
    } else {
        let mut handles = Vec::new();
        for _ in 0..nthreads {
            let sh = shared.clone();
            let cfg = cfg.clone();
            handles.push(std::thread::spawn(move || loop {
                let task = {
                    let mut g = sh.lock().unwrap();
                    g.queue.pop()
                };
                match task {
                    Some(t) => process_task(&sh, t, &cfg),
                    None => break,
                }
            }));
        }
        for h in handles {
            let _ = h.join();
        }
    }

    let mut sh = Arc::try_unwrap(shared)
        .ok()
        .map(|m| m.into_inner().unwrap())
        .unwrap();
    let mut nodes = std::mem::take(&mut sh.nodes);
    let root = match single_dir_root {
        Some(id) => id,
        None => 0,
    };
    for i in (0..nodes.len()).rev() {
        let mut total = nodes[i].size;
        let mut count = 1u64;
        let children = nodes[i].children.clone();
        for c in children {
            total += nodes[c].total;
            count += nodes[c].count;
        }
        nodes[i].total = total;
        nodes[i].count = count;
    }
    Graph {
        nodes,
        root,
        smallest: sh.smallest.unwrap_or(0),
        largest: sh.largest,
    }
}

fn abs_of(p: &Path) -> String {
    match fs::canonicalize(p) {
        Ok(c) => c.to_string_lossy().to_string(),
        Err(_) => {
            if p.is_absolute() {
                p.to_string_lossy().to_string()
            } else {
                let mut s = std::env::current_dir()
                    .map(|c| c.to_string_lossy().to_string())
                    .unwrap_or_default();
                if !s.ends_with('/') {
                    s.push('/');
                }
                s.push_str(&p.to_string_lossy());
                s
            }
        }
    }
}

fn process_task(sh: &Arc<Mutex<Shared>>, task: Task, cfg: &Arc<Options>) {
    let Task {
        id,
        path,
        is_root,
        dev,
    } = task;
    let entries = match fs::read_dir(&path) {
        Ok(e) => e,
        Err(_) => return,
    };
    let mut children: Vec<(Vec<u8>, Node, Option<PathBuf>, Option<u64>)> = Vec::new();
    for ent in entries.flatten() {
        let name_bytes = ent.file_name().as_encoded_bytes().to_vec();
        let child_path = ent.path();
        let md = match fs::symlink_metadata(&child_path) {
            Ok(m) => m,
            Err(_) => continue,
        };
        let ft = md.file_type();
        if cfg.stay_on_fs {
            if let (Some(d), Some(ed)) = (dev, md.dev().ok()) {
                if d != ed {
                    continue;
                }
            }
        }
        if ft.is_symlink() {
            if is_root {
                continue;
            }
            children.push((
                name_bytes.clone(),
                mk_node(&String::from_utf8_lossy(&name_bytes), 0, false, true),
                None,
                None,
            ));
            continue;
        }
        if ft.is_dir() {
            let abs = abs_of(&child_path);
            let ignored = cfg.ignore_dirs.contains(&abs);
            let sz = own_size(&md, cfg.apparent_size);
            let nd = mk_node(&String::from_utf8_lossy(&name_bytes), sz, true, false);
            if ignored {
                children.push((name_bytes, nd, None, None));
            } else {
                children.push((
                    name_bytes,
                    nd,
                    Some(child_path),
                    md.dev().ok(),
                ));
            }
            continue;
        }
        let sz = own_size(&md, cfg.apparent_size);
        let sz = if cfg.count_hard_links {
            sz
        } else {
            let key = (md.dev().unwrap_or(0), md.ino().unwrap_or(0));
            let mut g = sh.lock().unwrap();
            if g.inodes.contains(&key) {
                0
            } else {
                g.inodes.insert(key);
                sz
            }
        };
        {
            let mut g = sh.lock().unwrap();
            track(&mut g, sz);
        }
        children.push((
            name_bytes,
            mk_node(&String::from_utf8_lossy(&name_bytes), sz, false, false),
            None,
            None,
        ));
    }
    children.sort_by(|a, b| a.0.cmp(&b.0));
    let mut g = sh.lock().unwrap();
    let mut ids = Vec::new();
    for (_name, node, subdir, subdev) in children {
        let cid = g.nodes.len();
        g.nodes.push(node);
        ids.push(cid);
        if let Some(p) = subdir {
            g.queue.push(Task {
                id: cid,
                path: p,
                is_root: false,
                dev: subdev,
            });
        }
    }
    g.nodes[id].children = ids;
}
RSEOF
echo ok"}

