    pub io_errors: u64,
}

pub struct Graph {
    pub nodes: Vec<Node>,
    pub root: usize,
    pub smallest: u64,
    pub largest: u64,
}

impl Graph {
    pub fn node(&self, id: usize) -> &Node {
        &self.nodes[id]
    }
    pub fn children(&self, id: usize) -> &[usize] {
        &self.nodes[id].children
    }
    pub fn total_visible(&self) -> u64 {
        self.nodes[self.root].total.saturating_sub(self.nodes[self.root].size)
    }
    pub fn visible_count(&self) -> u64 {
