//! The `aggregate` sub command: traversal, sorting and printing.

use crate::cli::Parsed;
use crate::fmt::Format;
use crate::tree::{self, Graph};
use std::fs;
use std::io::Write;

pub struct Row {
    pub name: String,
    pub size: u64,
    pub is_dir: bool,
    pub errors: u64,
}

pub fn default_inputs() -> Vec<String> {
    let mut v = Vec::new();
    if let Ok(rd) = fs::read_dir(".") {
        for e in rd.flatten() {
            v.push(String::from_utf8_lossy(e.file_name().as_encoded_bytes()).to_string());
        }
    }
    v
}

pub fn run(p: &Parsed) -> i32 {
    let inputs = if p.inputs.is_empty() {
        default_inputs()
    } else {
        p.inputs.clone()
    };
    let opts = crate::tree::Options {
        apparent_size: p.apparent_size,
        count_hard_links: p.count_hard_links,
        stay_on_fs: p.stay_on_fs,
        ignore_dirs: tree::collect_ignores(&p.ignore_dirs),
        threads: p.threads as usize,
    };
    let graph = tree::build(&inputs, &opts);
    if p.stats {
        eprintln!(
            "Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}",
            graph.entries_traversed(),
            graph.smallest,
            graph.largest
        );
    }
    print_graph(p, &graph)
}

pub fn rows_of(p: &Parsed, graph: &Graph) -> Vec<Row> {
    let mut rows = Vec::new();
    for &c in graph.children(graph.root) {
        let n = graph.node(c);
        rows.push(Row {
            name: n.name.clone(),
            size: n.total,
            is_dir: n.is_dir,
            errors: n.io_errors,
        });
    }
    if !p.no_sort {
        let mut idx: Vec<usize> = (0..rows.len()).collect();
        idx.sort_by(|a, b| rows[*a].size.cmp(&rows[*b].size));
        let mut sorted: Vec<Row> = Vec::with_capacity(rows.len());
        let mut taken = vec![false; rows.len()];
        for i in idx {
            taken[i] = true;
            sorted.push(Row {
                name: rows[i].name.clone(),
                size: rows[i].size,
                is_dir: rows[i].is_dir,
                errors: rows[i].errors,
            });
        }
        rows = sorted;
    }
    rows
}

pub fn render_row(f: Format, r: &Row, errors: Option<u64>) -> String {
    let mut s = String::new();
    s.push_str("\x1b[32m");
    s.push_str(&f.format(r.size));
    s.push_str("\x1b[39m ");
    if r.is_dir {
        s.push_str("\x1b[36m");
        s.push_str(&r.name);
        s.push_str("\x1b[39m");
    } else {
        s.push_str(&r.name);
    }
    let errs = errors.unwrap_or(r.errors);
    if errs > 0 {
        s.push_str(&format!(
            "  <{} IO Error{}>",
            errs,
            if errs == 1 { "" } else { "s" }
        ));
    }
    s
}

pub fn print_graph(p: &Parsed, graph: &Graph) -> i32 {
    let rows = rows_of(p, graph);
    let mut out: Vec<String> = Vec::new();
    for r in &rows {
        out.push(render_row(p.format, r, None));
    }
    if rows.len() > 1 && !p.no_total {
        let total: u64 = rows.iter().map(|r| r.size).sum();
        out.push(render_row(
            p.format,
            &Row {
                name: "total".to_string(),
                size: total,
                is_dir: false,
                errors: 0,
            },
            Some(graph.io_errors()),
        ));
    }
    let mut rc = if graph.io_errors() > 0 { 1 } else { 0 };
    let mut reported = false;
    for line in &out {
        match writeln!(std::io::stdout(), "{}", line) {
            Ok(_) => {}
            Err(e) => {
                if !reported {
                    reported = true;
                    let _ = writeln!(std::io::stderr(), "Error: {}", e);
                    rc = 1;
                }
            }
        }
    }
    let _ = std::io::stdout().flush();
    rc
}
RSEOF
echo ok"}

