            self.set(cx, y, ch, st);
            cx += 1;
        }
        cx
    }

    /// Write text and pad with spaces up to `width`.
    pub fn put_pad(&mut self, x: usize, y: usize, text: &str, width: usize, st: Style) -> usize {
        let mut cx = x;
        let mut n = 0usize;
        for ch in text.chars() {
            if n >= width {
                break;
            }
            self.set(cx, y, ch, st);
            cx += 1;
            n += 1;
        }
        while n < width {
            self.set(cx, y, ' ', st);
            cx += 1;
            n += 1;
        }
        cx
    }
}

/// Renderer that writes only what changed, similar to the original tool.
pub struct Renderer {
    prev: Screen,
    cur_style: Style,
}

impl Renderer {
    pub fn new(cols: usize, rows: usize) -> Renderer {
        Renderer {
            prev: Screen::new(cols, rows),
            cur_style: Style::default(),
        }
    }

    pub fn resize(&mut self, cols: usize, rows: usize) {
        self.prev = Screen::new(cols, rows);
    }

    pub fn draw(&mut self, out: &mut Vec<u8>, s: &Screen) {
        let mut cx = usize::MAX;
        let mut cy = usize::MAX;
        let mut started = false;
        for y in 0..s.rows {
            for x in 0..s.cols {
                let i = y * s.cols + x;
                if s.chars[i] == self.prev.chars[i] && s.styles[i] == self.prev.styles[i] {
                    continue;
                }
                if !started {
                    started = true;
                    // position at the start of the row
                    out.extend_from_slice(format!("\x1b[{};{}H", y + 1, x + 1).as_bytes());
                    cx = x;
                    cy = y;
                } else if cy != y || cx != x {
                    out.extend_from_slice(format!("\x1b[{};{}H", y + 1, x + 1).as_bytes());
                    cx = x;
                    cy = y;
                }
                if s.styles[i] != self.cur_style {
                    let mut seq = String::new();
                    sgr_diff(&self.cur_style, &s.styles[i], &mut seq);
                    out.extend_from_slice(seq.as_bytes());
                    self.cur_style = s.styles[i];
                }
                let mut buf = [0u8; 4];
                out.extend_from_slice(s.chars[i].encode_utf8(&mut buf).as_bytes());
                cx += 1;
            }
            // after a row, cells that were not visited keep their position
        }
        self.prev.chars = s.chars.clone();
        self.prev.styles = s.styles.clone();
        out.extend_from_slice(b"\x1b[?25l");
    }
}

pub fn enter_screen(w: &mut impl Write) {
    let _ = w.write_all(b"\x1b[?1049h\x1b[?25l\x1b[2J");
}
pub fn leave_screen(w: &mut impl Write) {
    let _ = w.write_all(b"\x1b[?25h\x1b[?1049l");
}
