use std::io::Write;

#[repr(C)]
#[derive(Clone, Copy)]
pub struct Termios {
    pub c_iflag: u32,
    pub c_oflag: u32,
    pub c_cflag: u32,
    pub c_lflag: u32,
    pub c_line: u8,
    pub c_cc: [u8; 32],
    pub c_ispeed: u32,
    pub c_ospeed: u32,
}

extern "C" {
    fn tcgetattr(fd: i32, termios_p: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, optional_actions: i32, termios_p: *const Termios) -> i32;
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TCSANOW: i32 = 0;
const TIOCGWINSZ: u64 = 0x5413;

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

pub struct Terminal {
    pub orig: Termios,
    pub raw_set: bool,
}

impl Terminal {
    pub fn enter() -> Option<Terminal> {
        let mut t = Termios {
            c_iflag: 0,
            c_oflag: 0,
            c_cflag: 0,
            c_lflag: 0,
            c_line: 0,
            c_cc: [0; 32],
            c_ispeed: 0,
            c_ospeed: 0,
        };
        unsafe {
            if tcgetattr(0, &mut t as *mut Termios) != 0 {
                return None;
            }
        }
        let orig = t;
        // cfmakeraw equivalent
        t.c_iflag &= !(0o1 | 0o2 | 0o40 | 0o100 | 0o400 | 0o2000 | 0o40000 | 0o100000);
        t.c_iflag |= 0o400; // ICRNL
        t.c_oflag &= !0o1;
        t.c_oflag &= !0o4;
        t.c_cflag &= !(0o20 | 0o60 | 0o100); // CSIZE/PARENB
        t.c_cflag |= 0o40; // CS8
        t.c_cflag &= !0o100000; // CRTSCTS
        t.c_cflag |= 0o200; // CREAD
        t.c_lflag &= !(0o10 | 0o2 | 0o100000 | 0o2000 | 0o4000); // ECHO|ICANON|ISIG|IEXTEN|ECHOK
        t.c_cc[6] = 1; // VMIN
        t.c_cc[5] = 0; // VTIME
        unsafe {
            if tcsetattr(0, TCSANOW, &t as *const Termios) != 0 {
                return None;
            }
        }
        Some(Terminal {
            orig,
            raw_set: true,
        })
    }

    pub fn restore(&mut self) {
        if self.raw_set {
            unsafe {
                tcsetattr(0, TCSANOW, &self.orig as *const Termios);
            }
            self.raw_set = false;
        }
    }

    pub fn size() -> (u16, u16) {
        let mut ws = Winsize::default();
        unsafe {
            if ioctl(0, TIOCGWINSZ, &mut ws as *mut Winsize) == 0 && ws.ws_col > 0 {
                (ws.ws_col, ws.ws_row)
            } else {
                (80, 24)
            }
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Default, Debug)]
pub struct Style {
    pub bold: bool,
    pub underline: bool,
    pub reverse: bool,
    pub blink: bool,
    pub dim: bool,
    pub hidden: bool,
    pub fg: Option<u8>,
    pub bg: Option<u8>,
}

pub const BLACK: u8 = 0;
pub const WHITE: u8 = 15;
pub const GREEN: u8 = 2;
pub const CYAN: u8 = 6;
pub const RED: u8 = 1;
pub const GREY: u8 = 8;

impl Style {
    pub fn fg(c: u8) -> Style {
        Style {
            fg: Some(c),
            ..Default::default()
        }
    }
}

fn sgr_diff(prev: &Style, next: &Style, out: &mut String) {
    let mut seq = String::new();
    let mut reset = false;
    // Reverse / hidden / dim transitions need a reset to be safe.
    if prev.reverse != next.reverse || prev.hidden != next.hidden {
        reset = true;
    }
    if reset {
        seq.push_str("\x1b[0m");
    }
    if prev.bold != next.bold {
        seq.push_str(if next.bold { "\x1b[1m" } else { "\x1b[22m" });
    }
    if prev.underline != next.underline {
        seq.push_str(if next.underline { "\x1b[4m" } else { "\x1b[24m" });
    }
    if prev.blink != next.blink {
        seq.push_str(if next.blink { "\x1b[6m" } else { "\x1b[25m" });
    }
    if next.reverse && !prev.reverse {
        seq.push_str("\x1b[7m");
    }
    if next.hidden && !prev.hidden {
        seq.push_str("\x1b[8m");
    }
    if prev.dim != next.dim {
        seq.push_str(if next.dim { "\x1b[2m" } else { "\x1b[22m" });
    }
    if prev.fg != next.fg {
        match next.fg {
            Some(c) => seq.push_str(&format!("\x1b[38;5;{}m", c)),
            None => seq.push_str("\x1b[39m"),
        }
    }
    if prev.bg != next.bg {
        match next.bg {
            Some(c) => seq.push_str(&format!("\x1b[48;5;{}m", c)),
            None => seq.push_str("\x1b[49m"),
        }
    }
    out.push_str(&seq);
}

pub struct Screen {
    pub cols: usize,
    pub rows: usize,
    pub chars: Vec<char>,
    pub styles: Vec<Style>,
}

impl Screen {
    pub fn new(cols: usize, rows: usize) -> Screen {
        Screen {
            cols,
            rows,
            chars: vec![' '; cols * rows],
            styles: vec![Style::default(); cols * rows],
        }
    }

    pub fn set(&mut self, x: usize, y: usize, ch: char, st: Style) {
        if x >= self.cols || y >= self.rows {
            return;
        }
        self.chars[y * self.cols + x] = ch;
        self.styles[y * self.cols + x] = st;
    }

    pub fn style_at(&self, x: usize, y: usize) -> Style {
        self.styles[y * self.cols + x]
    }
    pub fn char_at(&self, x: usize, y: usize) -> char {
        self.chars[y * self.cols + x]
    }

    /// Write `text` starting at (x, y) using `st`, returning the new x.
    pub fn put(&mut self, x: usize, y: usize, text: &str, st: Style) -> usize {
        let mut cx = x;
