//! Interactive (TUI) mode.

use crate::term::*;
use crate::tree::{self, Graph, Options};
use std::collections::VecDeque;
use std::fs;
use std::io::{IsTerminal, Read, Write};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

const LEGEND_MAIN: &str = " mark-move = d | mark-toggle = space | toggle-all = a ";
const LEGEND_MARKED: &str = " mark-toggle = space,d | remove-all = a";
const LEGEND_HELP: &str = "";

const SORT_SIZE: &str = "size";
const SORT_MODIFIED: &str = "modified";
const SORT_ITEMS: &str = "items";
const SORT_NAME: &str = "name";

#[derive(Clone, Copy, PartialEq, Eq)]
enum Sort {
    Size(bool),
    Modified(bool),
    Items(bool),
    Name(bool),
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Disp {
    PctBar,
    PctOnly,
    BarOnly,
    BarWide,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Pane {
    Main,
    Marked,
    Help,
}

struct Shared {
    graph: Option<Graph>,
    done: bool,
    processed: u64,
}

pub struct App {
    pub graph: Arc<Mutex<Shared>>,
    pub scanning: Arc<AtomicBool>,
    pub inputs: Vec<String>,
    pub opts: Options,
    pub start: Instant,
    pub root: usize,
    /// path of node ids from the root to the current view
    pub path: Vec<usize>,
    pub sel: usize,
    pub offset: usize,
    pub sort: Sort,
    pub disp: Disp,
    pub show_mtime: bool,
    pub show_count: bool,
    pub marked: Vec<usize>,
    pub pane: Pane,
    pub help_open: bool,
    pub marked_open: bool,
    pub marked_sel: usize,
    pub marked_offset: usize,
    pub cols: usize,
    pub rows: usize,
    pub renderer: Renderer,
    pub screen: Screen,
    pub search: Option<String>,
    pub message: Option<String>,
    pub quit: bool,
}

impl App {
    pub fn new(inputs: Vec<String>, opts: Options, no_entry_check: bool) -> App {
        let _ = no_entry_check;
        let graph = Arc::new(Mutex::new(Shared {
            graph: None,
            done: false,
            processed: 0,
        }));
        let scanning = Arc::new(AtomicBool::new(true));
        let g2 = graph.clone();
        let s2 = scanning.clone();
        let inp = inputs.clone();
        let o2 = opts.clone();
        std::thread::spawn(move || {
            let g = tree::build(&inp, &o2);
            let mut sh = g2.lock().unwrap();
            sh.graph = Some(g);
            sh.done = true;
            drop(sh);
            s2.store(false, Ordering::SeqCst);
        });
        let (cols, rows) = Terminal::size();
        let (cols, rows) = (cols.max(20) as usize, rows.max(6) as usize);
        App {
            graph,
            scanning,
            inputs,
            opts,
            start: Instant::now(),
            root: usize::MAX,
            path: Vec::new(),
            sel: 0,
            offset: 0,
            sort: Sort::Size(false),
            disp: Disp::PctBar,
            show_mtime: false,
            show_count: false,
            marked: Vec::new(),
            pane: Pane::Main,
            help_open: false,
            marked_open: false,
            marked_sel: 0,
            marked_offset: 0,
            cols,
            rows,
            renderer: Renderer::new(cols, rows),
            screen: Screen::new(cols, rows),
            search: None,
            message: None,
            quit: false,
        }
    }

    fn take_graph(&mut self) -> Option<Graph> {
        let mut sh = self.graph.lock().unwrap();
        sh.graph.take()
    }

    fn processed(&self) -> u64 {
        let sh = self.graph.lock().unwrap();
        match &sh.graph {
            Some(g) => g.entries_traversed(),
            None => 0,
        }
    }

    fn is_scanning(&self) -> bool {
        self.scanning.load(Ordering::SeqCst)
    }

    fn cur(&self) -> usize {
        *self.path.last().unwrap_or(&self.root)
    }

    fn n_children(&self, g: &Graph, id: usize) -> usize {
        g.children(id).len()
    }

    fn sort_children(&self, g: &Graph, children: &[usize]) -> Vec<usize> {
        let mut v: Vec<usize> = children.to_vec();
        let asc = match self.sort {
            Sort::Size(a) | Sort::Modified(a) | Sort::Items(a) | Sort::Name(a) => a,
        };
        match self.sort {
            Sort::Size(_) => {
                v.sort_by(|a, b| {
                    let s = g.node(*a).total.cmp(&g.node(*b).total);
                    let s = if asc { s } else { s.reverse() };
                    s.then_with(|| g.node(*b).name.as_bytes().cmp(g.node(*a).name.as_bytes()))
                });
            }
            Sort::Modified(_) => {
                v.sort_by(|a, b| {
                    let s = mtime_of(g, *a).cmp(&mtime_of(g, *b));
                    let s = if asc { s } else { s.reverse() };
                    s.then_with(|| g.node(*b).name.as_bytes().cmp(g.node(*a).name.as_bytes()))
                });
            }
            Sort::Items(_) => {
                v.sort_by(|a, b| {
                    let s = g.node(*a).count.cmp(&g.node(*b).count);
                    let s = if asc { s } else { s.reverse() };
                    s.then_with(|| {
                        if asc {
                            g.node(*a).name.as_bytes().cmp(g.node(*b).name.as_bytes())
                        } else {
                            g.node(*b).name.as_bytes().cmp(g.node(*a).name.as_bytes())
                        }
                    })
                });
            }
            Sort::Name(_) => {
                v.sort_by(|a, b| {
                    let s = g.node(*a).name.as_bytes().cmp(&g.node(*b).name.as_bytes());
                    if asc {
                        s
                    } else {
                        s.reverse()
                    }
                });
            }
        }
        v
    }
}

fn mtime_of(_g: &Graph, _id: usize) -> u64 {
    0
}

pub fn run(inputs: Vec<String>, opts: Options, no_entry_check: bool) -> i32 {
    if !std::io::stdin().is_terminal() || !std::io::stdout().is_terminal() {
        eprintln!("Error: Interactive mode requires a connected terminal");
        return 1;
    }
    let mut term = match Terminal::enter() {
        Some(t) => t,
        None => {
            eprintln!("Error: Interactive mode requires a connected terminal");
            return 1;
        }
    };
    let mut app = App::new(inputs, opts, no_entry_check);
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    enter_screen(&mut out);
    let mut buf: Vec<u8> = Vec::new();
    let mut result = 0;
    loop {
        // pull in traversal results
        if let Some(g) = app.take_graph() {
            app.root = g.root;
            app.path = vec![g.root];
            app.sel = 0;
            app.offset = 0;
            app.graph.lock().unwrap().graph = Some(g);
        }
        app.render(&mut buf);
        let _ = out.write_all(&buf);
        let _ = out.flush();
        buf.clear();
        // read keys with a small timeout so we can poll the traversal
        let mut ch = [0u8; 64];
        match read_key(&mut ch, &app) {
            0 => {
                if app.quit {
                    break;
                }
            }
            _ => {
                let keys = decode_keys(&ch[..]);
                for k in keys {
                    app.handle_key(&k);
                    if app.quit {
                        break;
                    }
                }
            }
        }
        if app.quit {
            break;
        }
        if app.is_scanning() {
            std::thread::sleep(Duration::from_millis(40));
        }
    }
    leave_screen(&mut out);
    term.restore();
    result
}

/// Wait for input, polling the traversal state.
fn read_key(buf: &mut [u8], _app: &App) -> usize {
    let mut stdin = std::io::stdin();
    let mut n = 0usize;
    loop {
        match stdin.read(&mut buf[n..]) {
            Ok(0) => break,
            Ok(k) => {
                n += k;
                break;
            }
            Err(_) => break,
        }
    }
    n
}

fn decode_keys(data: &[u8]) -> Vec<String> {
    let mut keys = Vec::new();
    let mut i = 0usize;
    while i < data.len() {
        let b = data[i];
        if b == 0x1b {
            // escape sequences
            if i + 1 < data.len() && data[i + 1] == b'[' {
                let mut j = i + 2;
                while j < data.len() && !(0x40..=0x7e).contains(&data[j]) {
                    j += 1;
                }
                if j < data.len() {
                    let seq = String::from_utf8_lossy(&data[i..=j]).to_string();
                    let key = match &seq {
                        "\x1b[A" => "Up",
                        "\x1b[B" => "Down",
                        "\x1b[C" => "Right",
                        "\x1b[D" => "Left",
                        "\x1b[H" => "Home",
                        "\x1b[F" => "End",
                        "\x1b[5~" => "PgUp",
                        "\x1b[6~" => "PgDn",
                        "\x1b[3~" => "Del",
                        _ => "",
                    };
                    if !key.is_empty() {
                        keys.push(key.to_string());
                    }
                    i = j + 1;
                    continue;
                }
            }
            keys.push("Esc".to_string());
            i += 1;
            continue;
        }
        match b {
            b'\r' | b'\n' => keys.push("Enter".to_string()),
            b'\t' => keys.push("Tab".to_string()),
            0x7f => keys.push("BSpace".to_string()),
            0x08 => keys.push("BSpace".to_string()),
            0x01..=0x1a => keys.push(format!("C-{}", (b'a' + b - 1) as char)),
            _ => {
                let s = decode_utf8(data, i);
                let len = s.len_utf8();
                keys.push(s.to_string());
                i += len;
                continue;
            }
        }
        i += 1;
    }
    keys
}

fn decode_utf8(data: &[u8], i: usize) -> &str {
    let b = data[i];
    let len = if b < 0x80 {
        1
    } else if b < 0xc0 {
        1
    } else if b < 0xe0 {
        2
    } else if b < 0xf0 {
        3
    } else {
        4
    };
    let end = (i + len).min(data.len());
    std::str::from_utf8(&data[i..end]).unwrap_or(" ")
}
RSEOF
echo "part1 ok""}

