    Modified(bool),
    Items(bool),
    Name(bool),
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Disp {
    PctBar,
    PctOnly,
    BarOnly,
    BarWide,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Pane {
    Main,
    Marked,
    Help,
}

struct Shared {
    graph: Option<Graph>,
    done: bool,
    processed: u64,
}

pub struct App {
    pub graph: Arc<Mutex<Shared>>,
    pub scanning: Arc<AtomicBool>,
    pub inputs: Vec<String>,
    pub opts: Options,
    pub start: Instant,
    pub root: usize,
    /// path of node ids from the root to the current view
    pub path: Vec<usize>,
    pub sel: usize,
    pub offset: usize,
    pub sort: Sort,
    pub disp: Disp,
    pub show_mtime: bool,
    pub show_count: bool,
    pub marked: Vec<usize>,
    pub pane: Pane,
    pub help_open: bool,
    pub marked_open: bool,
    pub marked_sel: usize,
    pub marked_offset: usize,
    pub cols: usize,
    pub rows: usize,
    pub renderer: Renderer,
    pub screen: Screen,
    pub search: Option<String>,
    pub message: Option<String>,
    pub quit: bool,
}

impl App {
    pub fn new(inputs: Vec<String>, opts: Options, no_entry_check: bool) -> App {
        let _ = no_entry_check;
        let graph = Arc::new(Mutex::new(Shared {
            graph: None,
            done: false,
            processed: 0,
        }));
        let scanning = Arc::new(AtomicBool::new(true));
        let g2 = graph.clone();
        let s2 = scanning.clone();
        let inp = inputs.clone();
        let o2 = opts.clone();
        std::thread::spawn(move || {
            let g = tree::build(&inp, &o2);
            let mut sh = g2.lock().unwrap();
            sh.graph = Some(g);
            sh.done = true;
            drop(sh);
            s2.store(false, Ordering::SeqCst);
        });
        let (cols, rows) = Terminal::size();
        let (cols, rows) = (cols.max(20) as usize, rows.max(6) as usize);
        App {
            graph,
            scanning,
            inputs,
            opts,
            start: Instant::now(),
            root: usize::MAX,
            path: Vec::new(),
            sel: 0,
            offset: 0,
            sort: Sort::Size(false),
            disp: Disp::PctBar,
