            marked_sel: 0,
            marked_offset: 0,
            cols,
            rows,
            renderer: Renderer::new(cols, rows),
            screen: Screen::new(cols, rows),
            search: None,
            message: None,
            quit: false,
        }
    }

    fn take_graph(&mut self) -> Option<Graph> {
        let mut sh = self.graph.lock().unwrap();
        sh.graph.take()
    }

    fn processed(&self) -> u64 {
