// ---------------------------------------------------------------- rendering

impl App {
    pub fn render(&mut self, buf: &mut Vec<u8>) {
        let (w, h) = Terminal::size();
        let (w, h) = (w.max(20) as usize, h.max(6) as usize);
        if w != self.cols || h != self.rows {
            self.cols = w;
            self.rows = h;
            self.renderer.resize(w, h);
            self.screen = Screen::new(w, h);
        }
        let graph_opt = self.graph.lock().unwrap().graph.take();
        if let Some(g) = graph_opt {
            self.graph.lock().unwrap().graph = Some(g);
        }
        let sh = self.graph.lock().unwrap();
        if let Some(g) = &sh.graph {
            let g: &Graph = g;
            let mut s = Screen::new(self.cols, self.rows);
            self.draw_title(&mut s);
            // layout of panes
            let two = self.help_open || self.marked_open;
            let main_w = if two {
                (self.cols + 1) / 2
            } else {
                self.cols
            };
            let second_x = main_w;
            let second_w = self.cols.saturating_sub(main_w);
            self.draw_pane_top(&mut s, g, 0, main_w);
            self.draw_rows(&mut s, g, 0, main_w);
            self.draw_pane_bottom(&mut s, 0, main_w);
            if two {
                match self.pane {
                    Pane::Help => self.draw_help_pane(&mut s, second_x, second_w),
                    _ => self.draw_marked_pane(&mut s, g, second_x, second_w),
                }
            }
            self.draw_status(&mut s, g);
            drop(sh);
            self.renderer.draw(buf, &s);
        } else {
            let mut s = Screen::new(self.cols, self.rows);
            self.draw_title(&mut s);
            self.draw_waiting(&mut s);
            drop(sh);
            self.renderer.draw(buf, &s);
        }
    }

    fn draw_title(&mut self, s: &mut Screen) {
        let base = Style {
            fg: Some(WHITE),
            bg: Some(BLACK),
            ..Default::default()
        };
        let bold = Style {
            bold: true,
            fg: Some(BLACK),
            bg: Some(WHITE),
            ..Default::default()
        };
        let underline = Style {
            underline: true,
            fg: Some(BLACK),
            bg: Some(WHITE),
            ..Default::default()
        };
        let pad = Style {
            fg: None,
            bg: Some(WHITE),
            ..Default::default()
        };
        let _ = base;
        let mut x = 0usize;
        let mut put = |s: &mut Screen, x: &mut usize, t: &str, st: Style| {
            for ch in t.chars() {
                if *x >= s.cols {
                    return;
                }
                s.set(*x, 0, ch, st);
                *x += 1;
            }
        };
        put(s, &mut x, " D", bold);
        put(s, &mut x, "isk ", Style { fg: Some(BLACK), bg: Some(WHITE), ..Default::default() });
        put(s, &mut x, "U", bold);
        put(s, &mut x, "sage ", Style { fg: Some(BLACK), bg: Some(WHITE), ..Default::default() });
        put(s, &mut x, "A", bold);
        put(
            s,
            &mut x,
            "nalyzer v2.32.2    ",
            Style {
                fg: Some(BLACK),
                bg: Some(WHITE),
                ..Default::default()
            },
        );
        put(s, &mut x, "(press ", underline);
        put(s, &mut x, "?", Style { bold: true, underline: true, fg: Some(BLACK), bg: Some(WHITE), ..Default::default() });
        put(s, &mut x, " for help)", underline);
        while x < s.cols {
            s.set(x, 0, ' ', pad);
            x += 1;
        }
    }

    fn draw_waiting(&mut self, s: &mut Screen) {
        let border = Style {
            bold: true,
            ..Default::default()
        };
        for y in 1..s.rows.saturating_sub(1) {
            s.set(0, y, '│', border);
            s.set(s.cols.saturating_sub(1), y, '█', Style { bold: true, reverse: true, ..Default::default() });
        }
    }

    fn rel_path(&self, g: &Graph) -> String {
        if self.path.len() <= 1 {
            return g.node(g.root).name.clone();
        }
        let mut parts: Vec<String> = Vec::new();
        for i in 1..self.path.len() {
            parts.push(g.node(self.path[i]).name.clone());
        }
        parts.join("/")
    }

    fn draw_pane_top(&mut self, s: &mut Screen, g: &Graph, x0: usize, w: usize) {
        let st = Style {
            bold: true,
            ..Default::default()
        };
        let rev = Style {
            bold: true,
            reverse: true,
            ..Default::default()
        };
        if w == 0 {
            return;
        }
        s.set(x0, 1, '┌', st);
        let legend = LEGEND_MAIN;
        let title = self.main_title(g);
        let inner = w.saturating_sub(2);
        if inner >= title.chars().count() + legend.chars().count() {
            let mut x = x0 + 1;
            x = self.put_title(s, x, 1, &title, &st, &rev);
            let dashes = inner - title.chars().count() - legend.chars().count();
            for _ in 0..dashes {
                s.set(x, 1, '─', st);
                x += 1;
            }
            for ch in legend.chars() {
                s.set(x, 1, ch, st);
                x += 1;
            }
        } else {
            let mut x = x0 + 1;
            let avail = inner;
            let mut n = 0usize;
            for ch in title.chars() {
                if n >= avail {
                    break;
                }
                s.set(x, 1, ch, st);
                x += 1;
                n += 1;
            }
        }
        s.set(x0 + w - 1, 1, '┐', st);
    }

    fn put_title(
        &self,
        s: &mut Screen,
        mut x: usize,
        y: usize,
        title: &str,
        st: &Style,
        rev: &Style,
    ) -> usize {
        // title = " path (V visible, T total, SIZE) " with highlighted numbers
        let mut rest = title;
        // leading space
        if let Some(c) = rest.chars().next() {
            s.set(x, y, c, *st);
            x += 1;
            rest = &rest[1..];
        }
        // path until " ("
        if let Some(pos) = rest.find(" (") {
            for ch in rest[..pos].chars() {
                s.set(x, y, ch, *st);
                x += 1;
            }
            s.set(x, y, ' ', *st);
            x += 1;
            s.set(x, y, '(', *st);
            x += 1;
            rest = &rest[pos + 2..];
            // visible count until " visible"
            if let Some(p) = rest.find(" visible") {
                for ch in rest[..p].chars() {
                    s.set(x, y, ch, *rev);
                    x += 1;
                }
                for ch in " visible, ".chars() {
                    s.set(x, y, ch, *st);
                    x += 1;
                }
                rest = &rest[p + 9..];
            }
            if let Some(p) = rest.find(" total") {
                for ch in rest[..p].chars() {
                    s.set(x, y, ch, *rev);
                    x += 1;
                }
                for ch in " total, ".chars() {
                    s.set(x, y, ch, *st);
                    x += 1;
                }
                rest = &rest[p + 7..];
            }
            // remaining is "SIZE) " -> highlight all
            for ch in rest.chars() {
                s.set(x, y, ch, *rev);
                x += 1;
            }
        } else {
            for ch in rest.chars() {
                s.set(x, y, ch, *st);
                x += 1;
            }
        }
        x
    }

    fn main_title(&self, g: &Graph) -> String {
        let root = g.node(g.root);
        let mut base = if self.path.len() <= 1 {
            root.name.clone()
        } else {
            self.rel_path(g)
        };
        if base.is_empty() {
            base = cwd_string();
        }
        let vis = g.children(self.cur()).len();
        let total = g.descendant_count_of(self.cur());
        let size = g.total_visible_of(self.cur());
        let size_str = crate::fmt::Format::Binary
            .format(size)
            .trim_start_matches(' ')
            .to_string();
        format!(
            " {} ({} visible, {} total, {}) ",
            base, vis, total, size_str
        )
    }

    fn draw_pane_bottom(&mut self, s: &mut Screen, x0: usize, w: usize) {
        let st = Style {
            bold: true,
            ..Default::default()
        };
        if w == 0 {
            return;
        }
        let y = s.rows - 2;
        s.set(x0, y, '└', st);
        let legend = match self.pane {
            Pane::Main if !self.marked_open && !self.help_open => LEGEND_MAIN,
            Pane::Marked => LEGEND_MARKED,
            _ => "",
        };
        let inner = w.saturating_sub(2);
        let llen = legend.chars().count();
        if llen > 0 && inner >= llen {
            let dashes = inner - llen;
            for _ in 0..dashes {
                s.set(x0 + 1, y, '─', st);
            }
            let mut x = x0 + 1 + dashes;
            for ch in legend.chars() {
                s.set(x, y, ch, st);
                x += 1;
            }
        } else {
            for _ in 0..inner {
                s.set(x0 + 1, y, '─', st);
            }
        }
        s.set(x0 + w - 1, y, '┘', st);
    }

    fn draw_status(&mut self, s: &mut Screen, g: &Graph) {
        let st = Style {
            reverse: true,
            ..Default::default()
        };
        let scanning = Style {
            bold: true,
            blink: true,
            fg: Some(RED),
            ..Default::default()
        };
        let mut text = String::new();
        text.push_str("Sort mode: ");
        text.push_str(&self.sort_label());
        text.push_str("  Total disk usage: ");
        text.push_str(&crate::fmt::Format::Binary.format(g.total_visible()));
        text.push_str("  Processed ");
        let n = self.processed();
        text.push_str(&n.to_string());
        text.push_str(" entries in ");
        let el = self.start.elapsed().as_secs_f64();
        if el < 0.005 {
            text.push_str("0s");
        } else {
            text.push_str(&format!("{:.2}s", el));
        }
        let scanning_now = self.is_scanning();
        if scanning_now {
            text.push_str(&format!(" ({}/s)", (n as f64 / el.max(1e-9)) as u64));
        }
        let mut x = 0usize;
        for ch in text.chars() {
            if x >= s.cols {
                break;
            }
            s.set(x, s.rows - 1, ch, st);
            x += 1;
        }
        if scanning_now {
            let tail = "-> scanning";
            let mut tx = s.cols.saturating_sub(tail.chars().count());
            for ch in tail.chars() {
                s.set(tx, s.rows - 1, ch, scanning);
                tx += 1;
            }
        }
        while x < s.cols {
            s.set(x, s.rows - 1, ' ', st);
            x += 1;
        }
    }

    fn sort_label(&self) -> String {
        match self.sort {
            Sort::Size(a) => format!("{} {}", SORT_SIZE, if a { "ascending" } else { "descending" }),
            Sort::Modified(a) => format!("{} {}", SORT_MODIFIED, if a { "ascending" } else { "descending" }),
            Sort::Items(a) => format!("{} {}", SORT_ITEMS, if a { "ascending" } else { "descending" }),
            Sort::Name(a) => format!("{} {}", SORT_NAME, if a { "ascending" } else { "descending" }),
        }
    }

    fn show_pct(&self) -> bool {
        matches!(self.disp, Disp::PctBar | Disp::PctOnly)
    }
    fn show_bar(&self) -> bool {
        matches!(self.disp, Disp::PctBar | Disp::BarOnly | Disp::BarWide)
    }
    fn bar_width(&self) -> usize {
        match self.disp {
            Disp::BarWide => 19,
            _ => 10,
        }
    }

    fn draw_rows(&mut self, s: &mut Screen, g: &Graph, x0: usize, w: usize) {
        if w < 2 {
            return;
        }
        let inner = w - 2;
        let content_rows = s.rows - 4;
        let cur = self.cur();
        let kids = self.sort_children(g, g.children(cur));
        let n = kids.len();
        // clamp the selection and offset
        if self.sel >= n {
            self.sel = n.saturating_sub(1);
        }
        if content_rows > 0 {
            if self.sel < self.offset {
                self.offset = self.sel;
            }
            if self.sel >= self.offset + content_rows {
                self.offset = self.sel + 1 - content_rows;
            }
        }
        let border = Style {
            bold: true,
            ..Default::default()
        };
        let scroll = Style {
            bold: true,
            reverse: true,
            ..Default::default()
        };
        // scrollbar
        let track = content_rows;
        let thumb = if n > 0 {
            (track as f64 * track as f64 / (track + n as i64 - 1) as f64).round() as usize
        } else {
            track as usize
        };
        let thumb = thumb.clamp(1, track);
        let pos = if n > 1 {
            let range = track as f64 - thumb as f64;
            (range * self.sel as f64 / (n as f64 - 1.0)).round() as usize
        } else {
            0
        };
        let pos = pos.min(track.saturating_sub(thumb));
        for y in 0..content_rows {
            let ch = if y >= pos && y < pos + thumb { '█' } else { '║' };
            s.set(x0 + w - 1, 2 + y, ch, scroll);
        }
        // rows
        for i in 0..content_rows {
            let idx = self.offset + i;
            let y = 2 + i;
            s.set(x0, y, '│', border);
            if idx >= n {
                // empty row
                let mut x = x0 + 1;
                while x < x0 + w - 1 {
                    s.set(x, y, ' ', Style::default());
                    x += 1;
                }
                continue;
            }
            self.draw_entry(s, g, x0, w, y, kids[idx], idx == self.sel);
        }
    }

    fn draw_entry(&mut self, s: &mut Screen, g: &Graph, x0: usize, w: usize, y: usize, id: usize, selected: bool) {
        let node = g.node(id);
        let mut x = x0 + 1;
        let end = x0 + w - 1;
        let sel_base = Style {
            reverse: selected,
            ..Default::default()
        };
        let size_st = Style {
            fg: Some(GREEN),
            reverse: selected,
            ..Default::default()
        };
        // mtime column
        if self.show_mtime {
            x = s.put_pad(x, y, &mtime_str(node), 20, Style { fg: None, reverse: selected, ..Default::default() });
            x = s.put(x, y, " | ", Style { fg: None, reverse: selected, ..Default::default() });
        }
        // size
        x = s.put_pad(x, y, &crate::fmt::Format::Binary.format(node.total), 11, size_st);
        x = s.put(x, y, " | ", Style { fg: None, reverse: selected, ..Default::default() });
        // percent
        if self.show_pct() {
            let total = g.total_visible_of(self.cur());
            let pct = if total > 0 { node.total as f64 * 100.0 / total as f64 } else { 0.0 };
            let pct_str = format!("{:.1}%", pct);
            x = s.put_pad(x, y, &pct_str, 7, Style { fg: None, reverse: selected, ..Default::default() });
            x = s.put(x, y, " ", Style { fg: None, reverse: selected, ..Default::default() });
        }
        // bar
        if self.show_bar() {
            if self.show_pct() {
                s.set(x, y, ' ', Style { fg: None, reverse: selected, ..Default::default() });
                x += 1;
            }
            let total = g.total_visible_of(self.cur());
            let frac = if total > 0 { node.total as f64 / total as f64 } else { 0.0 };
            let cells = self.bar_width();
            let filled = (frac * cells as f64).floor() as usize;
            let rem = frac * cells as f64 - filled as f64;
            for i in 0..cells {
                let ch = if i < filled {
                    '█'
                } else if i == filled {
                    let e = (rem * 8.0).round() as i32;
                    match e {
                        0 => ' ',
                        1 => '▏',
                        2 => '▎',
                        3 => '▍',
                        4 => '▌',
                        5 => '▋',
                        6 => '▊',
                        7 => '▉',
                        _ => '█',
                    }
                } else {
                    ' '
                };
                s.set(x, y, ch, Style { fg: None, reverse: selected, ..Default::default() });
                x += 1;
            }
        }
        x = s.put(x, y, " | ", Style { fg: None, reverse: selected, ..Default::default() });
        if self.show_count {
            let c = if node.is_dir {
                format!("{:4}", node.count.saturating_sub(1))
            } else {
                "    ".to_string()
            };
            x = s.put_pad(x, y, &c, 4, Style { fg: None, reverse: selected, ..Default::default() });
            x = s.put(x, y, " | ", Style { fg: None, reverse: selected, ..Default::default() });
        }
        // name
        let avail = end.saturating_sub(x);
        let name = display_name(node);
        let name_st = Style {
            fg: if node.is_dir { Some(CYAN) } else { None },
            reverse: selected,
            ..Default::default()
        };
        let mut n = 0usize;
        for ch in name.chars() {
            if n >= avail {
                break;
            }
            s.set(x + n, y, ch, name_st);
            n += 1;
        }
        while n < avail {
            s.set(x + n, y, ' ', name_st);
            n += 1;
        }
    }

    fn draw_marked_pane(&mut self, s: &mut Screen, _g: &Graph, x0: usize, w: usize) {
        let st = Style {
            bold: true,
            ..Default::default()
        };
        let active = self.pane == Pane::Marked;
        if w == 0 {
            return;
        }
        let y = 1;
        s.set(x0, y, '┌', st);
        let total: u64 = 0;
        let title = format!("Marked {} items ({}) ", self.marked.len(), crate::fmt::Format::Binary.format(total).trim_start_matches(' '));
        let mut x = x0 + 1;
        for ch in title.chars() {
            if x >= x0 + w - 1 {
                break;
            }
            s.set(x, y, ch, st);
            x += 1;
        }
        while x < x0 + w - 1 {
            s.set(x, y, '─', st);
            x += 1;
        }
        s.set(x0 + w - 1, y, '┐', st);
        // body
        let content_rows = s.rows - 4;
        let mut idx = 0usize;
        if active {
            let hint = "Ctrl + t  to trash or  Ctrl + r  to delete without prompt";
            let mut hx = x0 + 1;
            for ch in hint.chars() {
                if hx >= x0 + w - 1 {
                    break;
                }
                s.set(hx, 2, ch, Style::default());
                hx += 1;
            }
            while hx < x0 + w - 1 {
                s.set(hx, 2, ' ', Style::default());
                hx += 1;
            }
            idx = 1;
        }
        for i in 0..content_rows.saturating_sub(idx) {
            let y2 = 2 + idx + i;
            s.set(x0, y2, '│', st);
            let _ = i;
        }
        self.draw_pane_bottom(s, x0, w);
    }

    fn draw_help_pane(&mut self, s: &mut Screen, x0: usize, w: usize) {
        let st = Style {
            bold: true,
            ..Default::default()
        };
        if w == 0 {
            return;
        }
        s.set(x0, 1, '┌', st);
        let mut x = x0 + 1;
        for ch in "Help".chars() {
            if x >= x0 + w - 1 {
                break;
            }
            s.set(x, 1, ch, st);
            x += 1;
        }
        while x < x0 + w - 1 {
            s.set(x, 1, '─', st);
            x += 1;
        }
        s.set(x0 + w - 1, 1, '┐', st);
        let content_rows = s.rows - 4;
        let help = help_lines();
        for i in 0..content_rows {
            let y = 2 + i;
            s.set(x0, y, '│', st);
            if let Some(line) = help.get(i) {
                let mut hx = x0 + 1;
                for ch in line.chars() {
                    if hx >= x0 + w - 1 {
                        break;
                    }
                    s.set(hx, y, ch, Style::default());
                    hx += 1;
                }
                while hx < x0 + w - 1 {
                    s.set(hx, y, ' ', Style::default());
                    hx += 1;
                }
            }
        }
        self.draw_pane_bottom(s, x0, w);
    }
}

fn display_name(n: &tree::Node) -> String {
    if n.is_dir {
        format!("/{}", n.name)
    } else {
        format!(" {}", n.name)
    }
}

fn cwd_string() -> String {
    std::env::current_dir()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_default()
}

fn mtime_str(_n: &tree::Node) -> String {
    String::new()
}

fn help_lines() -> Vec<String> {
    let mut v = Vec::new();
    let sections: [(&str, &[&str]); 4] = [
        (
            "Pane control",
            &[
                "     q/<Esc> => Close the current pane.",
                "                Closes the program if no pane is open.",
                "       <Tab> => Cycle between all open panes.",
                "                Activate 'Marked Items' pane to delete selected files.",
                "           ? => Show or hide this help pane.",
            ],
        ),
        (
            "Navigation",
            &[
                "    j/<Down> => Move down 1 entry.",
                "      k/<Up> => Move up 1 entry.",
                " o/l/<Enter> => Descent into the selected directory.",
                "     <Right> => ^",
                "  u/h/<Left> => Ascent one level into the parent directory.",
                " <Backspace> => ^",
                "    Ctrl + d => Move down 10 entries.",
                " <Page Down> => ^",
                "    Ctrl + u => Move up 10 entries.",
                "   <Page Up> => ^",
                "    H/<Home> => Move to the top of the list.",
                "     G/<End> => Move to the bottom of the list.",
            ],
        ),
        (
            "Display",
            &[
                "           s => Toggle sort by size descending/ascending.",
                "           m => Toggle sort by modified time descending/ascending.",
                "           M => Show/hide modified time.",
                "           c => Toggle sort by entries descending/ascending.",
                "           C => Show/hide entry count.",
                "           n => Toggle sort by name ascending/descending.",
                "         g/S => Cycle through percentage display and bar options.",
            ],
