//! Move entries to the trash directory (XDG style) when available.

use std::fs;
use std::path::Path;

pub fn trash(p: &Path) -> std::io::Result<()> {
    let base = std::env::var_os("XDG_DATA_HOME")
        .map(PathBuf::from)
        .or_else(|| {
            std::env::var_os("HOME").map(|h| {
                let mut b = std::path::PathBuf::from(h);
                b.push(".local/share");
                b
            })
        });
    let base = match base {
        Some(b) => b,
        None => return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "no home")),
    };
    let dir = base.join("Trash/files");
    let _ = fs::create_dir_all(&dir);
    let name = p.file_name().map(|s| s.to_os_string()).unwrap_or_default();
    let mut target = dir.join(&name);
    let mut n = 1;
    while target.exists() {
        target = dir.join(format!("{}.{}", name.to_string_lossy(), n));
        n += 1;
    }
    fs::rename(p, &target)
}
use std::path::PathBuf;
RSEOF
echo ok"}

