// ---------------------------------------------------------------- key handling

impl App {
    fn cur_children(&self, g: &Graph) -> Vec<usize> {
        self.sort_children(g, g.children(self.cur()))
    }

    fn move_sel(&mut self, g: &Graph, delta: i64) {
        let n = self.cur_children(g).len() as i64;
        if n == 0 {
            return;
        }
        let mut s = self.sel as i64 + delta;
        if s < 0 {
            s = 0;
        }
        if s >= n {
            s = n - 1;
        }
        self.sel = s as usize;
    }

    fn toggle_mark(&mut self, g: &Graph, id: usize) {
        if let Some(pos) = self.marked.iter().position(|&m| m == id) {
            self.marked.remove(pos);
        } else {
            self.marked.push(id);
        }
        if !self.marked_open {
            self.marked_open = true;
            self.pane = Pane::Main;
        }
    }

    fn marked_items(&self, g: &Graph) -> u64 {
        self.marked.iter().map(|&m| g.node(m).count).sum()
    }
    fn marked_size(&self, g: &Graph) -> u64 {
        self.marked.iter().map(|&m| g.node(m).total).sum()
    }

    pub fn handle_key(&mut self, k: &str) {
        let mut g = self.graph.lock().unwrap().graph.take();
        let has = g.is_some();
        let mut gg = g.take();
        if has {
            let g = gg.as_mut().unwrap();
            self.on_key(g, k);
        } else {
            match k {
                "q" | "Esc" => self.quit = true,
                _ => {}
            }
        }
        if let Some(g) = gg {
            self.graph.lock().unwrap().graph = Some(g);
        }
    }

    fn on_key(&mut self, g: &mut Graph, k: &str) {
        match k {
            "q" | "Esc" => {
                if self.help_open || self.marked_open {
                    self.help_open = false;
                    self.marked_open = false;
                    self.pane = Pane::Main;
                } else {
                    self.quit = true;
                }
            }
            "?" => {
                self.help_open = !self.help_open;
                if self.help_open {
                    self.pane = Pane::Help;
                } else {
                    self.pane = Pane::Main;
                }
            }
            "Tab" => {
                if self.marked_open {
                    self.pane = if self.pane == Pane::Marked {
                        if self.help_open {
                            Pane::Help
                        } else {
                            Pane::Main
                        }
                    } else if self.pane == Pane::Help {
                        Pane::Main
                    } else {
                        Pane::Marked
                    };
                } else if self.help_open {
                    self.pane = if self.pane == Pane::Help {
                        Pane::Main
                    } else {
                        Pane::Help
                    };
                }
            }
            "j" | "Down" => self.move_sel(g, 1),
            "k" | "Up" => self.move_sel(g, -1),
            "C-d" | "PgDn" => self.move_sel(g, 10),
            "C-u" | "PgUp" => self.move_sel(g, -10),
            "H" | "Home" => self.move_sel(g, -(1 << 40)),
            "G" | "End" => self.move_sel(g, 1 << 40),
            "o" | "l" | "Enter" | "Right" => {
                let kids = self.cur_children(g);
                if let Some(&id) = kids.get(self.sel) {
                    if g.node(id).is_dir {
                        self.path.push(id);
                        self.sel = 0;
                        self.offset = 0;
                    }
                }
            }
            "h" | "u" | "Left" | "BSpace" => {
                if self.path.len() > 1 {
                    let parent = self.path[self.path.len() - 2];
                    let cur = self.cur();
                    self.path.pop();
                    self.sel = 0;
                    self.offset = 0;
                    let kids = self.cur_children(g);
                    if let Some(pos) = kids.iter().position(|&c| c == cur) {
                        self.sel = pos;
                    }
                    let _ = parent;
                }
            }
            "s" => {
                self.sort = match self.sort {
                    Sort::Size(a) => Sort::Size(!a),
                    _ => Sort::Size(true),
                };
            }
            "m" => {
                self.sort = match self.sort {
                    Sort::Modified(a) => Sort::Modified(!a),
                    _ => Sort::Modified(false),
                };
            }
            "c" => {
                self.sort = match self.sort {
                    Sort::Items(a) => Sort::Items(!a),
                    _ => Sort::Items(false),
                };
            }
            "n" => {
                self.sort = match self.sort {
                    Sort::Name(a) => Sort::Name(!a),
                    _ => Sort::Name(true),
                };
            }
            "M" => self.show_mtime = !self.show_mtime,
            "C" => self.show_count = !self.show_count,
            "g" | "S" => {
                self.disp = match self.disp {
                    Disp::PctBar => Disp::PctOnly,
                    Disp::PctOnly => Disp::BarOnly,
                    Disp::BarOnly => Disp::BarWide,
                    Disp::BarWide => Disp::PctBar,
                };
            }
            "d" => {
                let kids = self.cur_children(g);
                if let Some(&id) = kids.get(self.sel) {
                    self.toggle_mark(g, id);
                    self.move_sel(g, 1);
                }
            }
            " " => {
                let kids = self.cur_children(g);
                if let Some(&id) = kids.get(self.sel) {
                    self.toggle_mark(g, id);
                }
            }
            "x" => {
                let kids = self.cur_children(g);
                if let Some(&id) = kids.get(self.sel) {
                    if !self.marked.contains(&id) {
                        self.marked.push(id);
                    }
                    if !self.marked_open {
                        self.marked_open = true;
                    }
                    self.move_sel(g, 1);
                }
            }
            "a" => {
                if self.pane == Pane::Marked {
                    self.marked.clear();
                } else {
                    let kids = self.cur_children(g);
                    let all = kids.iter().all(|&c| self.marked.contains(&c));
                    if all {
                        for &c in &kids {
                            self.marked.retain(|&m| m != c);
                        }
                    } else {
                        for &c in &kids {
                            if !self.marked.contains(&c) {
                                self.marked.push(c);
                            }
                        }
                    }
                }
            }
            "C-r" => {
                let ids = self.marked.clone();
                let mut removed = 0u64;
                for id in ids {
                    let p = self.path_of(g, id);
                    let _ = fs::remove_dir_all(&p).or_else(|_| fs::remove_file(&p));
                    removed += g.node(id).count;
                }
                self.marked.clear();
                let _ = removed;
            }
            "C-t" => {
                let ids = self.marked.clone();
                for id in ids {
                    let p = self.path_of(g, id);
                    let _ = crate::trash::trash(&p);
                }
                self.marked.clear();
            }
            _ => {}
        }
    }

    fn path_of(&self, g: &Graph, id: usize) -> PathBuf {
        // reconstruct path by walking the tree structure from the root
        let mut stack = vec![(g.root, String::new())];
        while let Some((node, prefix)) = stack.pop() {
            if node == id {
                return PathBuf::from(prefix);
            }
            for &c in g.children(node) {
                let child_name = g.node(c).name.clone();
                let np = if prefix.is_empty() {
                    if g.node(c).is_input {
                        child_name.clone()
                    } else {
                        format!("{}/{}", g.node(g.root).name, child_name)
                    }
                } else {
                    format!("{}/{}", prefix, child_name)
                };
                stack.push((c, np));
            }
        }
        PathBuf::new()
    }
}
