mod aggregate;
mod cli;
mod completions;
mod fmt;
mod term;
mod trash;
mod tree;
mod tui;

use std::io::Write;
use std::time::{SystemTime, UNIX_EPOCH};

fn hhmmss() -> String {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let d = secs % 86400;
    format!("{:02}:{:02}:{:02}", d / 3600, (d % 3600) / 60, d % 60)
}

fn debug_str_list(items: &[String]) -> String {
    if items.is_empty() {
        return "[]".to_string();
    }
    let mut s = String::from("[\n");
    for i in items {
        s.push_str(&format!("        \"{}\",\n", i));
    }
    s.push_str("    ]");
    s
}

fn log_args(p: &Option<crate::cli::Parsed>, log_file: &str) {
    let Some(p) = p else { return };
    let mut out = String::new();
    out.push_str(&format!("{} [INFO] dua options=", hhmmss()));
    let command = match p.sub {
        crate::cli::Sub::Aggregate => format!(
            "Some(\n        Aggregate {{\n            statistics: {},\n            no_sort: {},\n            no_total: {},\n            input: {},\n        }},\n    )",
            p.aggregate.map(|a| a.0).unwrap_or(false),
            p.aggregate.map(|a| a.1).unwrap_or(false),
            p.aggregate.map(|a| a.2).unwrap_or(false),
            debug_str_list(&p.inputs),
        ),
        crate::cli::Sub::Interactive => format!(
            "Some(\n        Interactive {{\n            no_entry_check: {},\n            input: {},\n        }},\n    )",
            p.interactive.unwrap_or(false),
            debug_str_list(&p.inputs),
        ),
        _ => "None".to_string(),
    };
    let fmt_name = match p.format {
        crate::fmt::Format::Metric => "Metric",
        crate::fmt::Format::Binary => "Binary",
        crate::fmt::Format::Bytes => "Bytes",
        crate::fmt::Format::Gb => "Gb",
        crate::fmt::Format::Gib => "Gib",
        crate::fmt::Format::Mb => "Mb",
        crate::fmt::Format::Mib => "Mib",
    };
    let inputs_dbg = if p.sub == crate::cli::Sub::None {
        debug_str_list(&p.inputs)
    } else {
        "[]".to_string()
    };
    out.push_str(&format!(
        "Args {{\n    command: {},\n    threads: {},\n    format: {},\n    apparent_size: {},\n    count_hard_links: {},\n    stay_on_filesystem: {},\n    ignore_dirs: {},\n    input: {},\n    log_file: Some(\n        \"{}\",\n    ),\n}}\n",
        command,
        p.threads,
        fmt_name,
        p.apparent_size,
        p.count_hard_links,
        p.stay_on_fs,
        debug_str_list(&p.ignore_dirs),
        inputs_dbg,
        log_file,
    ));
    out.push_str(&format!(
        "{} [INFO] Ignoring canonicalized {}\n",
        hhmmss(),
        crate::tree::collect_ignores(&p.ignore_dirs)
            .iter()
            .map(|d| format!("\"{}\"", d))
            .collect::<Vec<_>>()
            .join(", ")
    ));
    if let Ok(mut f) = std::fs::File::create(log_file) {
        let _ = f.write_all(out.as_bytes());
    }
}

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    let argv0 = argv.first().cloned().unwrap_or_else(|| "dua".to_string());
    let rest: Vec<String> = argv.iter().skip(1).cloned().collect();
    let c = cli::Cli::new(&argv0);
    let mut parsed: Option<crate::cli::Parsed> = None;
    let code = match c.parse(&rest) {
        crate::cli::Action::Help(h) => {
            print!("{}", h);
            let _ = std::io::stdout().flush();
            0
        }
        crate::cli::Action::Version => {
            print!("{}", c.version());
            let _ = std::io::stdout().flush();
            0
        }
        crate::cli::Action::Completions(shell) => {
            match crate::completions::script(&shell) {
                Some(s) => {
                    print!("{}", s);
                    let _ = std::io::stdout().flush();
                    0
                }
                None => 2,
            }
        }
        crate::cli::Action::Error(e) => {
            eprint!("{}", e);
            2
        }
        crate::cli::Action::Run(p) => {
            if let Some(lf) = &p.log_file {
                log_args(&Some(p.clone()), lf);
            }
            parsed = Some(p.clone());
            match p.sub {
                crate::cli::Sub::Aggregate => crate::aggregate::run(&p),
                crate::cli::Sub::Interactive => {
                    let opts = crate::tree::Options {
                        apparent_size: p.apparent_size,
                        count_hard_links: p.count_hard_links,
                        stay_on_fs: p.stay_on_fs,
                        ignore_dirs: crate::tree::collect_ignores(&p.ignore_dirs),
                        threads: p.threads as usize,
                    };
                    crate::tui::run(p.inputs.clone(), opts, p.interactive.unwrap_or(false))
                }
                _ => crate::aggregate::run(&p),
            }
        }
    };
    std::process::exit(code);
}
