import sys, re, subprocess, time
sys.path.insert(0,'/tmp')
from screen import parse, dump
def cap(cmd, cols, rows, keys, tag):
    tmux=['tmux','kill-server']; subprocess.run(tmux, stderr=subprocess.DEVNULL); time.sleep(0.5)
    subprocess.run(['tmux','new-session','-d','-s','c','-x',str(cols),'-y',str(rows),'--']+cmd)
    time.sleep(2.2)
    for k in keys:
        for kk in k.split('+'):
            if len(kk)==1: subprocess.run(['tmux','send-keys','-t','c','-l',kk])
            else: subprocess.run(['tmux','send-keys','-t','c',kk], stderr=subprocess.DEVNULL)
        time.sleep(0.9)
    time.sleep(1.0)
    r=subprocess.run(['tmux','capture-pane','-t','c','-p','-e'],capture_output=True)
    subprocess.run(['tmux','kill-server'], stderr=subprocess.DEVNULL)
    s=parse(r.stdout, cols, rows)
    return s
def cmp(cmd, cols, rows, keys):
    so=cap(['/workspace/executable']+cmd, cols, rows, keys,'o')
    sm=cap(['/tmp/executable']+cmd, cols, rows, keys,'m')
    bad=0
    for y in range(rows):
        for x in range(cols):
            if so.ch[y][x]!=sm.ch[y][x] or so.st[y][x]!=sm.st[y][x]:
                if bad<6: print('  cell(%d,%d) orig=%r/%r mine=%r/%r' % (x,y,so.ch[y][x],so.st[y][x],sm.ch[y][x],sm.st[y][x]))
                bad+=1
    print('  cells differing:', bad, 'of', rows*cols)
    return bad
if __name__=='__main__':
    import json
    cfg=json.loads(sys.argv[1])
