old = rest[:end]
new = '''    fn draw_marked_pane(&self, s: &mut Screen, g: &Graph, x0: usize, w: usize) {
        let st = Style {
            bold: true,
            ..Default::default()
        };
        let active = self.pane == Pane::Marked;
        if w == 0 {
            return;
        }
        let y = 1;
        s.set(x0, y, '┌', st);
        let items = self.marked_items(g);
        let size = self.marked_size(g);
        let size_str = crate::fmt::Format::Binary
            .format(size)
            .trim_start_matches(' ')
            .to_string();
        let title = format!("Marked {} items ({}) ", items, size_str);
        let mut x = x0 + 1;
        for ch in title.chars() {
            if x >= x0 + w - 1 {
                break;
            }
            s.set(x, y, ch, st);
            x += 1;
        }
        while x < x0 + w - 1 {
            s.set(x, y, '─', st);
            x += 1;
        }
        s.set(x0 + w - 1, y, '┐', st);

        let content_rows = s.rows - 4;
        let mut row = 0usize;
        if active {
            let hint = "Ctrl + t  to trash or  Ctrl + r  to delete without prompt";
            let mut hx = x0 + 1;
            for ch in hint.chars() {
                if hx >= x0 + w - 1 {
                    break;
                }
                s.set(hx, 2, ch, Style::default());
                hx += 1;
            }
            while hx < x0 + w - 1 {
                s.set(hx, 2, ' ', Style::default());
                hx += 1;
            }
            row = 1;
        }
        let border = Style {
            bold: true,
            ..Default::default()
        };
        let scroll = Style {
            bold: true,
            reverse: true,
            ..Default::default()
        };
        let available = content_rows.saturating_sub(row);
        let n = self.marked.len();
        // scrollbar for the marked pane
        if w >= 2 {
            let track = available;
            let thumb = if n > 0 {
                (track as f64 * track as f64 / (track as f64 + n as f64 - 1.0))
                    .round() as usize
            } else {
                track
            };
            let thumb = thumb.clamp(1, track.max(1));
            let pos = if n > 1 {
                let range = track as f64 - thumb as f64;
                (range * self.marked_sel as f64 / (n as f64 - 1.0)).round() as usize
            } else {
                0
            };
            let pos = pos.min(track.saturating_sub(thumb));
            for i in 0..track {
                let ch = if i >= pos && i < pos + thumb { '█' } else { '║' };
                s.set(x0 + w - 1, 2 + row + i, ch, scroll);
            }
        }
        for i in 0..available {
            let y2 = 2 + row + i;
            s.set(x0, y2, '│', border);
            let mid = i;
            if mid >= n {
                let mut cx = x0 + 1;
                while cx < x0 + w - 1 {
                    s.set(cx, y2, ' ', Style::default());
                    cx += 1;
                }
                continue;
            }
            let id = self.marked[mid];
            let node = g.node(id);
            let selected = mid == self.marked_sel && active;
            let inner = w - 2;
            let name_w = inner.saturating_sub(13);
            let name = display_name(node);
            let name_st = Style {
                fg: if node.is_dir { Some(CYAN) } else { None },
                reverse: selected,
                ..Default::default()
            };
            let mut cx = x0 + 1;
            let mut k = 0usize;
            for ch in name.chars() {
                if k >= name_w {
                    break;
                }
                s.set(cx, y2, ch, name_st);
                cx += 1;
                k += 1;
            }
            while k < name_w {
                s.set(cx, y2, ' ', name_st);
                cx += 1;
                k += 1;
            }
            let sz = crate::fmt::Format::Binary.format(node.total);
            let size_st = Style {
                reverse: selected,
                ..Default::default()
            };
            let mut kk = 0usize;
            for ch in sz.chars() {
                s.set(cx + kk, y2, ch, size_st);
                kk += 1;
            }
            for _ in 0..2 {
                s.set(cx + kk, y2, ' ', size_st);
                kk += 1;
            }
        }
        self.draw_pane_bottom(s, x0, w);
    }

'''
